"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7154],{30193:(e,n,t)=>{t.d(n,{Y:()=>i});const i=[{id:"the-fool",name:{en:"The Fool",zh:"愚者"},arcana:"major",suit:null,number:0,description:{en:"A traveler walks leisurely with only the clothes on his back and a light bundle. He holds a white rose, celebrating freedom, yet does not notice that there is no road ahead. This card represents freedom and the unknown state of not knowing what comes next.",zh:"只有身上這套裝束，捎著輕鬆的行囊悠閒漫步的旅行者。他一手拿著白玫瑰，盡情謳歌著自由。不過在他腳邊，前方並沒有道路可走。〈愚者〉的牌呈現的是自由，以及不知道下一步會怎麼樣的未知狀態。"},coreKeyword:{en:"Freedom",zh:"自由"},meaning:{upright:{en:"Pure values free from preconceived notions, convention, or worldly judgment. By living according to one's own heart, unexpected opportunities and new ideas may emerge.",zh:"表現出不受「該這樣」的既定觀念、常識或世俗眼光所束縛的純粹價值觀，依照自己的心意生活的狀態。因此會有出乎意料的機會從天而降，或湧現嶄新的點子。"},reversed:{en:"Passive indecision stands out. Aimless drifting may bring loneliness, irresponsibility, and loss of trust from those around you.",zh:"凡事都猶豫不決的消極面特別顯眼。由於漫無目的地持續遊蕩，而遭受居無定所的孤獨感折磨。隨心所欲的個性也會被視為態度不負責任，導致失去周遭人們的信任。"}},readingAspects:{currentSituation:{upright:{en:"Something new begins / uncertain outcomes ahead / difficult to predict / the story starts / departure is near / shifting perspective",zh:"某種新事物展開/不知道會發生什麼事/難以預料/故事開始/啟程出發的時刻將近/想法轉變"},reversed:{en:"No clear direction / drifting without purpose / unstable position / unclear responsibility / indecision / unaware of serious risks",zh:"沒有明確方針/隨波逐流/立場不穩定/責任歸屬不明確/無法決定/沒有察覺嚴重的風險"}},innerState:{upright:{en:"Fresh ideas forming / pure feelings without deception or schemes / interest in novel things / strong curiosity / indifference to trivial matters",zh:"產生新的想法/沒有謊言或詭計的純粹心情/對新穎的事物感興趣/好奇心旺盛/不在意瑣事"},reversed:{en:"Reluctance to decide / stagnation / avoiding reality / inner confusion / tendency to ignore problems / hidden true feelings",zh:"還不想下決定/遲滯狀態/不想面對現實/連自己也不知道該怎麼做/想視而不見/隱藏內心真正的想法"}},rootCause:{upright:{en:"Scattered thoughts / acting independently and not fitting in with others / plans lack concrete form / unconventional ideas are misunderstood / lack of responsibility",zh:"想法並未統合/太常單獨行動而與周遭格格不入/計畫不夠具體/想法特立獨行而無法獲得理解/沒有責任感"},reversed:{en:"Self-centered focus / only addressing what's immediately in front / inconsistent responses / indecision and lack of determination",zh:"只考慮到自己的自私態度/只想應付眼前的狀況/應對態度不一致/優柔寡斷而欠缺決斷力"}},development:{upright:{en:"New beginning / a small matter becomes a trigger that moves fate / an event that prompts departure from current circumstances / shedding burdens and breaking free",zh:"新的開始/微不足道的小事將成為契機，推動命運/令人從現在所處環境踏上旅途的事件/放下重擔/解脫拘束"},reversed:{en:"An unclear future continues for a time / forced concealment of inner state / careless handling of everything / weak willpower and passive drift",zh:"看不見未來的情況會持續一陣子/不得不隱藏自己內心的狀況/一切敷衍了事的狀態/意志力薄弱而隨波逐流"}},advice:{upright:{en:"Notice unconventional possibilities / avoid forcing matters / relax a little more / disregard others' opinions / commit to leaving your current situation",zh:"留意不落俗套的想法/不用力過度/再放輕鬆一點/別在意周遭的目光/下定決心脫離現在的環境"},reversed:{en:"Without genuine responsibility, trust will be lost / stop deceiving yourself / face reality directly / reduce acting alone",zh:"如果不確實抱持責任感，會成為失去信任的原因/別欺騙自己/別從現實上別開視線，好好面對/減少單獨行動"}}},contextualMeanings:{love:{upright:{en:"A new encounter / romance may appear in unexpected places / easygoing mutual affection / unadorned charm",zh:"新的邂逅/在隨意外出的地點會遇上戀情/輕鬆的步調/兩情相悅/不加矯飾的魅力"},reversed:{en:"Indecisive attitude / casual romance / attraction to someone without life direction / multiple relationships / flirtation",zh:"猶豫不決的態度/只是玩玩的戀情/迷上沒有生活能力的異性/腳踏兩條船以上的關係/搭訕"}},work:{upright:{en:"New ideas emerge / freelance work / no fixed employment / career change to another field",zh:"閃現新的點子/以自由業身分工作/沒有固定工作/轉行到其他領域"},reversed:{en:"Trouble from lack of competence or irresponsibility / procrastination and overtime / pretending to work / lack of enthusiasm / laziness",zh:"能力不足、不負責任招致的麻煩/拖拖拉拉而加班/裝出在工作的模樣/沒有精神/懶惰"}},interpersonal:{upright:{en:"Staying true to your path without following others / fortunate coincidences / receiving timely hints",zh:"不隨人起舞/貫徹自己的道路/樂觀的偶然/聽見有提示作用的話語"},reversed:{en:"Acting alone and lacking cooperation / changing with the wind / careless social behavior / taking the easy way",zh:"單獨行動而欠缺協調性/見風轉舵/社交態度隨便/選擇輕鬆的方式"}},others:{upright:{en:"Winning without effort / purity / departure / dreamer / easy come, easy go / emptiness / freedom and spontaneity",zh:"不戰而勝/潔淨無瑕/啟程/追夢人/左手賺錢右手花錢/空白/自由而隨心所欲"},reversed:{en:"Desire to escape / travel mishaps / careless decisions / selfish attitude / unfulfilled expectations",zh:"想要逃避/在旅行地點發生麻煩/隨便的主意/態度自私自利/期待落空"}}}},{id:"the-magician",name:{en:"The Magician",zh:"魔術師"},arcana:"major",suit:null,number:1,description:{en:"A young man confidently raises a wand, ready to demonstrate his skill. On the table before him are the four elements: wand, pentacle, sword, and cup. This card announces that everything is prepared, and the time to act has arrived.",zh:"男性意氣風發地高舉著魔杖，表情充滿自信，正準備大展身手。在前方桌上同時排著構成宇宙的四大要素——權杖、錢幣、寶劍與聖杯。這也是告知你萬事已經準備完成，展開行動的時刻終於到來的牌。"},coreKeyword:{en:"Creativity",zh:"創造力"},meaning:{upright:{en:"Clear awareness of what you want to do. There is no need to wait for support or preparation from others; you take initiative.",zh:"擁有「自己想怎麼做」的明確目標意識。因此不需要等待他人支援或準備，就會自動自發地展開行動。"},reversed:{en:"Confused reasoning for your actions and true confidence may not yet exist. Can also indicate misuse of talent or ability to deceive others.",zh:"「為什麼要那麼做」的想法模糊且心懷迷惘，或許還沒培養出真正的自信心。也可解釋成做出濫用才能欺騙人這類低階的行為。"}},readingAspects:{currentSituation:{upright:{en:"Standing at the starting line / everything is prepared / things proceed smoothly / perfect timing and circumstances / time to take the lead",zh:"正站在起跑線上/萬事俱備/周旋順利的時候/天時地利人和的機會/應當掌握主導權的情況"},reversed:{en:"Time to reconsider and reassess / many things are insufficient / getting by with words or tactics / wanting to move forward but blocked / lacking recognition",zh:"該停下腳步重新思考的時候/各方面都不夠充分/只能靠口才或手腕來度過難關的狀況/想前進卻窒礙難行/得不到周遭認同"}},innerState:{upright:{en:"Having something you want to do / thoughts are organized / wanting to start something new / enjoying interaction with others / seeking understanding / finding purpose",zh:"有想做的事/已經整理好想法/想展開某些新的事情/享受與他人交流/希望他人理解自己的想法/找到夢想"},reversed:{en:"Feeling confused / not grasping the essence of things / interpreting reality for your own benefit / lying / lacking confidence in your abilities / feeling pressured",zh:"有所迷惘/不了解事物的本質/依自己方便解釋現實/說謊/對才能沒有自信/快敗給周遭的反對"}},rootCause:{upright:{en:"Unfounded confidence / wrong method of advancement / all talk and no action / independent action without gaining others' understanding / poor explanation",zh:"毫無根據的自信/前進的方法有誤/只會空口說白話而不採取行動/特立獨行而無法獲得周遭的理解/說明不足"},reversed:{en:"Many other options remain / nothing is going smoothly / reaching saturation / events that erode confidence / public failure causing emotional trauma",zh:"還有更多其他方法/一切都沒有順利運作/已達飽和狀態/令人失去自信的事/在眾人面前失敗導致心理創傷"}},development:{upright:{en:"New developments emerge / smooth progress / beginning what you want to do / taking the initiative / opportunity to fully display your abilities",zh:"出現新的發展/一切事物順利進展/著手進行想做的事/率先展開行動/能大展長才的機會上門"},reversed:{en:"Things do not progress smoothly / somehow nothing works out / helpless situation / losing your mask / giving something up / being deceived / ideas are rejected",zh:"無法順利進展/不知為何很不順利/束手無策的狀態/假面具剝落/放棄什麼/被騙子欺騙/點子遭駁回"}},advice:{upright:{en:"Think and act independently without relying on others / hold your confidence / persuade the other person to gain understanding / do not fear standing in front / take the first step",zh:"自己思考行動而不假手他人/抱持自信/說服對方獲得理解/不要畏懼站在前頭/比任何人都率先邁出一步"},reversed:{en:"Do not give up halfway / before abandoning, there should still be something you can do / try a different approach / do not fear involvement with others / show conviction",zh:"不能中途撒手放棄/在放棄之前應該還有可以做到的事/嘗試其他做法/別害怕與人有所牽連/擁有堅強意志"}}},contextualMeanings:{love:{upright:{en:"Romance that realizes ideals / dating someone wonderful / active pursuit / rational approach",zh:"實現理想的戀情/與很棒的異性交往/積極出擊/理性的關係"},reversed:{en:"A relationship where you are used / a partner who only talks without acting / difficult romance / being deceived / romance fraud",zh:"被人利用的戀情/對光說不練的對象/棘手的戀情/受騙/婚姻詐欺"}},work:{upright:{en:"Displaying your abilities / enthusiastic engagement / realizing ideas or plans / work that utilizes your strengths",zh:"發揮才能/熱情地埋首其中/實現點子或企劃/能活用自身能力的工作"},reversed:{en:"Lack of work motivation / overwhelmed by work / considering a job change / wanting a different position",zh:"對工作提不起幹勁/工作忙不過來/考慮換工作/有其他想做的工作"}},interpersonal:{upright:{en:"Strong communication skills / smooth interactions / persuasive words / good at negotiation / expressing your views",zh:"高度溝通能力/左右逢源/話語具說服力/擅長交涉/表達意見"},reversed:{en:"Hesitant / uncomfortable dealing with others / superficial conversation / wanting distance / feeling out of place",zh:"優柔寡斷/不擅長應付對方/敷衍一時的對話/想保持距離的心情/格格不入"}},others:{upright:{en:"Positivity / quick thinking / knowledgeable / charm / winning through genuine ability / everything going as desired",zh:"積極性/腦筋轉得快/博學多聞/魅力/靠實力獲勝/凡事稱心如意"},reversed:{en:"Negativity / clumsiness / things not going smoothly / weak willpower / hitting obstacles everywhere / no way forward",zh:"消極性/笨拙/事情無法順遂/意志薄弱/四處碰壁/無路可走"}}}},{id:"the-high-priestess",name:{en:"The High Priestess",zh:"女祭司"},arcana:"major",suit:null,number:2,description:{en:"A mysterious woman crowned with the earth mother's crown sits between black and white pillars, holding the Torah. Her pure and noble bearing radiates wisdom, reason, and spiritual calm.",zh:"頭戴大地母神之冠的神祕女性坐在黑白雙柱之間，手持聖典。她散發純潔無瑕的高貴氣息，呈現智慧、理性與緊張感。"},coreKeyword:{en:"Spirituality",zh:"精神性"},meaning:{upright:{en:"Approaching matters with innate wisdom and reason / a noble spirit that remains impartial",zh:"藉由天生的智慧與理性掌握問題/擁有高潔精神，不偏袒任何一方"},reversed:{en:"Only seeing what you want to see / perfectionism and judgment becoming too prominent",zh:"只看見自己想看的事物/潔癖或完美主義過於顯眼"}},readingAspects:{currentSituation:{upright:{en:"Everything is prepared / a disciplined life / effort toward an ideal / time for learning / sharp intuition and insight",zh:"一切齊備/清心寡慾的生活/為了接近憧憬而努力/應當學習某事物/直覺與洞察力敏銳"},reversed:{en:"Overly tense and overwhelmed / the future cannot be predicted / pressure and distance from others",zh:"過於緊湊，應接不暇/未來無法預測/充滿壓力/與他人之間有隔閡"}},innerState:{upright:{en:"Serious in your understanding / strict with yourself / wanting clarity in all things / yearning for someone / underlying tension",zh:"認真地領會事物/不依賴人而嚴以律己/凡事都想黑白分明/強烈憧憬某人/下意識感到緊張"},reversed:{en:"Immature perspective / narrow worldview / resisting what's different / critical of others / prone to overreaction",zh:"精神上不成熟/眼界狹隘/抗拒不同事物/對他人抱持批判態度/容易歇斯底里"}},rootCause:{upright:{en:"Pursuing correct answers too intensely / overly rigid and inflexible / cold responses / difficult for others to approach",zh:"過度追求正確答案/過於潔癖而缺乏柔軟度/應對過於冷酷/散發他人難以靠近的氛圍"},reversed:{en:"Inflexible thinking / pretending to know / not listening to others / sudden emotional reactions / hiding inexperience",zh:"不知變通/不懂裝懂/不聽別人說話/立刻變得歇斯底里/隱瞞經驗不足"}},development:{upright:{en:"An opportunity to learn / important inspiration / noticing what matters / refining your goals / perceiving danger",zh:"出現學習某些事物的機會/獲得重要靈感/察覺重要事情/看見目標加以修正/察覺危險"},reversed:{en:"Losing calm amid panic / tendency toward extreme actions / isolation through criticism / mounting pressure",zh:"失去冷靜而陷入慌亂/容易採取極端行動/批判精神強烈而孤立/累積壓力"}},advice:{upright:{en:"Move toward your goal / discipline yourself / learn from the fundamentals / do not avoid what must be done",zh:"朝著目標邁進/嚴以律己/從基礎開始學習/別逃避該做的事"},reversed:{en:"Release pressure / manage your emotions / do not let information control you / move beyond immaturity / accept imperfection",zh:"抒發壓力/確實掌控情感/別被資訊牽著鼻子走/從少女階段畢業/接受包括缺點的一切"}}},contextualMeanings:{love:{upright:{en:"Approaching matters with wisdom and reason / maintaining impartiality",zh:"戀愛：藉由天生的智慧與理性掌握問題/擁有高潔精神，不偏袒任何一方"},reversed:{en:"Only seeing what you want / perfectionism becoming excessive",zh:"戀愛：只看見自己想看的事物/潔癖或完美主義過於顯眼"}},work:{upright:{en:"Approaching matters with wisdom and reason / maintaining impartiality",zh:"工作：藉由天生的智慧與理性掌握問題/擁有高潔精神，不偏袒任何一方"},reversed:{en:"Only seeing what you want / perfectionism becoming excessive",zh:"工作：只看見自己想看的事物/潔癖或完美主義過於顯眼"}},interpersonal:{upright:{en:"Approaching matters with wisdom and reason / maintaining impartiality",zh:"待人：藉由天生的智慧與理性掌握問題/擁有高潔精神，不偏袒任何一方"},reversed:{en:"Only seeing what you want / perfectionism becoming excessive",zh:"待人：只看見自己想看的事物/潔癖或完美主義過於顯眼"}},others:{upright:{en:"Approaching matters with wisdom and reason / maintaining impartiality",zh:"其他：藉由天生的智慧與理性掌握問題/擁有高潔精神，不偏袒任何一方"},reversed:{en:"Only seeing what you want / perfectionism becoming excessive",zh:"其他：只看見自己想看的事物/潔癖或完美主義過於顯眼"}}}},{id:"the-empress",name:{en:"The Empress",zh:"女皇"},arcana:"major",suit:null,number:3,description:{en:"The Empress sits comfortably in abundant nature. Her full figure suggests pregnancy, growth, unconditional love, and the endless cycle of life.",zh:"女皇舒適地端坐在豐饒結實的大自然中，豐腴的身材令人聯想到懷孕。這張牌象徵源源不絕的生命循環、愛、美與豐饒。"},coreKeyword:{en:"Abundance",zh:"豐饒"},meaning:{upright:{en:"Enjoying abundant blessings / naturally receiving love, beauty, wealth, and growth",zh:"盡情享受豐饒的收成/自然接受愛、美、財富與成長"},reversed:{en:"Tiring of excessive blessings / losing gratitude and becoming lazy or dependent",zh:"對過剩的恩惠感到厭煩/失去感謝而怠惰或依賴"}},readingAspects:{currentSituation:{upright:{en:"Material and spiritual abundance / gentle toward others / growing charm / positive developments",zh:"物質與精神上都游刃有餘/能對人溫柔/魅力正在提升/有喜事"},reversed:{en:"Complacent with the current state / dependency / indulgent lifestyle / frequent lack of self-control / saturation",zh:"對現狀坐享其成/依賴某人/慵懶無度/經常無法自制/飽和狀態"}},innerState:{upright:{en:"Calm and generous / accepting of all things / motherly love / desire to nurture",zh:"沉靜而游刃有餘/接受一切/如母親一般愛著某人/想要培育些什麼"},reversed:{en:"Too indulgent with yourself / confusing love with indulgence / dependency / excessive interference",zh:"對自己太好/搞錯愛與溺愛的差別/依賴某人或某物/過度干涉"}},rootCause:{upright:{en:"Kindness being exploited / too gentle and misunderstood / charm causing unwanted attention / jealousy and prejudice",zh:"愛或善意遭人利用/過於溫柔招致誤會/魅力或才能招惹麻煩/受到嫉妒或偏見"},reversed:{en:"Relying on outside forces / weak self-control / succumbing to temptation / overindulgence",zh:"依賴外力/沒有自制力/敗給誘惑/愛玩過頭"}},development:{upright:{en:"Affection becomes love / satisfying outcomes / material stability / mature charm flourishing / nurturing others",zh:"戀慕心變為愛情/得到滿意結果/物質上穩定/成熟魅力提升/培育人才"},reversed:{en:"Seeking the easier path / things do not go as planned / charm declining / unexpected pregnancy / failure through poor planning",zh:"選擇門檻較低的路/事情不按預定進行/魅力減退/出乎意料地懷孕/毫無計畫而失敗"}},advice:{upright:{en:"Be kind to everyone / forgive / express love through words / serve as a bridge / cooperate",zh:"對任何人都要溫柔/原諒對方/把愛多用言語表達/意識潤滑劑角色/互相協助"},reversed:{en:"Hold back and observe / maintain distance from overly close people / take time to rest / set boundaries / say no clearly",zh:"暫時觀望避免決定/與太親密的對象保持距離/保留休息時間/劃清界線/明確表達NO"}}},contextualMeanings:{love:{upright:{en:"Mutual love / nurturing affection / maternal love / joyful pregnancy",zh:"相愛的關係/以體貼培育愛情/母性的愛/令人欣喜的懷孕"},reversed:{en:"Mutual dependence / physical attraction / playboy behavior / infidelity / unexpected pregnancy",zh:"互相依存/肉體關係/花花公子/出軌/期望之外的懷孕"}},work:{upright:{en:"Profit and gain / comfortable workplace / cooperation / high compensation / smooth workflow",zh:"獲得利益/舒適職場/合作體制/高額報酬/工作方式順暢"},reversed:{en:"No gains or results / poor work performance / blurring of professional boundaries / laziness / underperforming",zh:"無法獲得利益或結果/工作成效不彰/公私混淆/心生怠惰/薪水小偷"}},interpersonal:{upright:{en:"Easygoing person / considerate maturity / creative dynamics / gentle connection",zh:"能夠放鬆的人/體貼待人成熟的人/具創造性的關係"},reversed:{en:"Superficial relationships / self-interested / pointless contact / poor habits",zh:"吊兒郎當的關係/只考慮自身利益的人/來往毫無益處的人/習慣性不檢"}},others:{upright:{en:"Gentleness / ease and comfort / financial security / elegance / luxury / charm",zh:"溫柔游刃有餘/財務寬裕/優雅/奢侈/魅力/才色兼備"},reversed:{en:"Naive thinking / overprotection / weak self-control / weight gain from indulgence / women's health issues",zh:"想法天真/過度保護/自制力不足/因放任自己而發胖/婦女病"}}}},{id:"the-emperor",name:{en:"The Emperor",zh:"皇帝"},arcana:"major",suit:null,number:4,description:{en:"The Emperor sits upon his throne in armor, ruling as a sovereign. He represents ambition, leadership, responsibility, and the power to stabilize a group.",zh:"身披鎧甲、堂堂端坐於王座上的男性是一國之君。這張牌呈現野心、統率力、責任感，以及穩定社會團體的力量。"},coreKeyword:{en:"Society",zh:"社會"},meaning:{upright:{en:"Establishing lasting stability / leading effectively and fulfilling your responsibility",zh:"獲得持續性的穩定/有效統率他人並盡到責任"},reversed:{en:"Using force for temporary stability / ruling harshly and eroding trust",zh:"藉由力量獲得一時的穩定/以力服人而瓦解信任"}},readingAspects:{currentSituation:{upright:{en:"Your efforts are bearing fruit / maintaining the current state / something has been built / time of strong responsibility / your abilities are being recognized",zh:"努力的成績確實開花結果的狀態/維持現狀的運氣/建構起某些事物的狀態/有高度責任感的時候/實力獲得評價"},reversed:{en:"Lack of follow-through / unstable fortune without direction / harsh reality blocking your path / losing sight of your goal / difficult to realize",zh:"後繼無力的狀況/不穩定且沒有目標的運氣/嚴峻的現實阻擋在面前/迷失目標而徬徨/難以實現"}},innerState:{upright:{en:"Strong conviction / pride in your accomplishments so far / wanting to fulfill your obligations / fearless confidence / wanting to lead / seeking independence",zh:"擁有堅定的自信/以至今為止的資歷為傲/想盡責任/充滿自信而無所畏懼/想立於頂端/想要獨立"},reversed:{en:"Bluffing / believing yourself unbiased / too pragmatic to dream / wanting to overpower others / unwilling to yield your position",zh:"虛張聲勢/認為自己並沒有逞強/過於現實而沒有夢想/想靠力量制伏他人/不想把現在的地位讓給任何人"}},rootCause:{upright:{en:"Too rigid and without room for compromise / an immovable, demonic presence / already complete with no room to grow / strong responsibility that burdens too much / loneliness at the top",zh:"過於光明正大而毫無妥協空間/難以撼動的魔王般的存在/已臻完成而沒有發展空間/有強烈責任感，過度背負一切/立於頂點的孤獨"},reversed:{en:"Spiritual instability / self-centered attitude / lack of courage / acting unilaterally with no followers / arrogance masking insecurity / refusing input",zh:"精神上不穩定/態度自私自利/沒有勇氣/獨斷獨行而無人跟隨/因為沒有自信而做出蠻橫行為/獨斷而不聽取他人意見"}},development:{upright:{en:"Building an unshakeable position / overwhelming others through ability / effective responses / emerging as a leader / ambition ignites / mental stability",zh:"建構起難以撼動的地位/憑實力令人甘拜下風/反應良好/成為領袖/燃起野心/精神上能游刃有餘"},reversed:{en:"Unable to fully control the situation / losing composure / criticism of your inadequacy / being removed from position / territorial conflict / failure through irresponsibility",zh:"狀況難以徹底掌控/內心沒有餘裕/遭人指責實力不足/被趕下原本的地位/引發爭奪地盤的紛爭/沒責任感而失敗"}},advice:{upright:{en:"Always conduct yourself with integrity / face matters without shifting blame / stabilize the current situation first / perseverance is strength / protect what matters",zh:"總是擺出光明磊落的態度/不推諉塞責而確實面對/第一步要穩定現況/堅持下去就是力量/應該保護重要的人"},reversed:{en:"Consider not only yourself but those around you / listening is important / be mindful of your tone / attend to the whole organization / use the power you have wisely",zh:"考慮自己之外，也要考慮周遭的事物/傾聽是很重要的/小心措辭直率過頭/關注組織整體/利用擁有的力量"}}},contextualMeanings:{love:{upright:{en:"A serious partner with understanding / a relationship prompting marriage consideration / stable long-term dating / responsibility / a strong-willed person",zh:"具包容力的人/令人考慮結婚的認真對象/正確的婚姻/長時間交往/責任感/硬派"},reversed:{en:"Selfishness / self-centeredness / hesitation about marriage / avoiding responsibility / instability due to indecision",zh:"自私自利/自我中心/對結婚感到猶豫/逃避責任/無法下定決心而不穩定的人"}},work:{upright:{en:"Reliable leadership / skill and competence / energetic management / efficient income generation / gaining both wealth and status",zh:"確實的領導能力/擇本領能幹/積極俐落地賺錢/同時獲得財富與地位"},reversed:{en:"Lack of conviction / insufficient ability / tired of inconsistency / no one wants to follow / overly meticulous",zh:"覺悟不夠/實力不足/厭煩沒有一致性/沒有人願意追隨自己/過於斤斤計較"}},interpersonal:{upright:{en:"Trustworthy in character and finances / unchanging friendship / long-term connection / leader type",zh:"無論為人或財務上都值得信任的人/不變的友誼/長年往來/經營者類型"},reversed:{en:"One-sided relationship / stubbornness / all appearance without substance / high-pressure approach / forceful, unreliable friend",zh:"單向的關係/倔強固執/虛有其表的人/高壓的態度/強硬的壞朋友"}},others:{upright:{en:"Strength / virility / grounded approach / fatherly nature / natural victory / something enduring / masculinity",zh:"強悍/有男子氣概/腳踏實地/父性/理所當然的勝利/一直存在的事物/男性化"},reversed:{en:"On the verge of collapse / cannot hold on / fleeting enthusiasm / not first, but second or third",zh:"即將崩毀/撐不住/三分鐘熱度/並非第一，而是第二或第三"}}}},{id:"the-hierophant",name:{en:"The Hierophant",zh:"教皇"},arcana:"major",suit:null,number:5,description:{en:"The Hierophant holds a triple cross and blesses two priests. He teaches morality, tradition, and the way to live, becoming a spiritual guide and trusted symbol.",zh:"教皇手持三重十字架，祝福兩名神父。他教導道德與生存之道，是精神上的榜樣，也是眾人信任與尊敬的存在。"},coreKeyword:{en:"Ethics",zh:"倫理道德"},meaning:{upright:{en:"Building trust and bonds through ethics, tradition, forgiveness, and faith",zh:"基於倫理道德締結信任與羈絆/尊重、原諒並信任他人"},reversed:{en:"Violating ethics / misusing trust and bonds for selfish purposes",zh:"違反倫理道德，利用信任與羈絆/背叛他人的信任"}},readingAspects:{currentSituation:{upright:{en:"Safe and peaceful fortune / maintaining order / a conflict-free atmosphere / environment that values ethics or tradition / seeking redemption / building good trust",zh:"平安無事的運氣/維持秩序/沒有紛爭的狀態/重視倫理道德或傳統的氛圍/追求救贖的時候/建立良好的信任關係"},reversed:{en:"Being forced into an inescapable situation / darkness approaching quietly / beginning to question your past self / loss of credibility",zh:"被逼上情非得已的狀況/魔掌暗中逼近/開始對至今為止的自己產生「這樣真的好嗎」的疑問/喪失信用"}},innerState:{upright:{en:"Respect for someone or something / valuing ethics and rules / desiring spiritual growth / interest in the spiritual realm / seeking meaning in life",zh:"尊重某人或某事/重視倫理道德或規範/想獲得精神上的成長/對靈性的世界產生興趣/想尋找生存意義"},reversed:{en:"Feeling this should not be so / unable to trust the person before you / malevolent thoughts / dependency on something / wanting to control hearts",zh:"認為事情不應如此，並非本意/無法相信眼前的對象/邪惡的想法/依賴某事物/想要控制人心"}},rootCause:{upright:{en:"Believing too much and losing sight of surroundings / bound by convention / rigid belief that promises must never break / fear of conflict / mutual dependency",zh:"過度相信某事物而看不見周遭/受到常識束縛/具有絕不能破壞約定的強硬觀念/過度畏懼與人起糾紛/互相依存"},reversed:{en:"Doubting the other person / attraction to immoral things / hypocritical behavior / rejection of differing values / cunning intentions",zh:"對對方抱持懷疑/受到不道德的事物吸引/偽善的言行舉止/無法接受與自己不同的價值觀/想法狡猾"}},development:{upright:{en:"Gaining trust / carrying others' expectations / encountering spiritual support / meeting a mentor-like figure / achievements recognized",zh:"取得對方的信任/肩負周遭期待的發展/遇見成為精神寄託的某種事物/出現師長般的存在/實績獲得認同"},reversed:{en:"Distrust toward the other party / doing something that cannot be shared / straying from the right path / being lured into immoral territory / falling for deception",zh:"對對方抱持不信任感/做出不能告訴他人的事情/偏離正軌，踏上失去理智的道路/被引誘到悖德的領域/中了美人計"}},advice:{upright:{en:"Carry through your beliefs no matter what / prioritize spiritual fulfillment over material gain / respect the rules / help others / first gain trust",zh:"無論發生任何事都要貫徹信念/比起物質，要優先於心靈上的滿足/守規則是很重要的/幫助他人/首先要獲得對方的信任"},reversed:{en:"Question what you have believed up until now / use what is available / avoid flattery / be wary of exposed hypocrisy",zh:"試著懷疑至今為止深信不疑的事物/能利用的東西就要利用才是正確/別聽信花言巧語/小心偽善的態度被識穿"}}},contextualMeanings:{love:{upright:{en:"A relationship that becomes spiritual support / someone worthy of respect / marriage-oriented dating / blessed marriage / reverence",zh:"能成為精神寄託的戀情/值得尊敬的人/以結婚為前提交往/受到祝福的婚姻/敬愛"},reversed:{en:"A relationship that cannot be made public / hidden desires / using sexuality as leverage / opportunistic relationship",zh:"無法公諸於世的關係/隱藏的欲望/試圖以性感作為武器/維持趁火打劫的關係"}},work:{upright:{en:"Work built on trust / fair dealings / teaching role / legal qualifications / established craft",zh:"建立在信任關係上的工作/好的交易/教職/與法律相關的證照/傳統專業工匠"},reversed:{en:"Loss of credibility / obvious fraud / unethical dealings / inability to keep promises",zh:"失去信用/顯而易見的詐欺/不擇手段地賤賣自己/無法遵守約定"}},interpersonal:{upright:{en:"Strong mutual trust / spiritual bond / someone safe to confide in / shared beliefs or values",zh:"信賴關係堅強/精神上的羈絆/可以放心託付一切的人/宗教觀或道德觀一致"},reversed:{en:"Unable to trust / goodwill being exploited / discomfort / incompatible values",zh:"無法信任/好感或善意遭人利用/感覺到不協調/與自己的價值觀不一致"}},others:{upright:{en:"Dignity / leadership / bearing expectations / strong persuasion / ceremonies / tradition / sacred religion and morality",zh:"尊貴/領袖魅力/背負期待/強大的說服力/婚喪喜慶/傳統/神聖的宗教道德"},reversed:{en:"Disorder / excessive freedom / suspicious origins / unpleasant conduct / illegal or immoral matters",zh:"失序/給予過度自由/來路不明/令人不愉快的言行舉止/違法不道德"}}}},{id:"the-lovers",name:{en:"The Lovers",zh:"戀人"},arcana:"major",suit:null,number:6,description:{en:"A man and woman in Eden are blessed by an angel. Their nakedness shows fearlessness, attraction, joy, and complete satisfaction.",zh:"伊甸園中的男女受到天使祝福，赤身裸體而毫無畏懼。這張牌展現一切獲得滿足、極為幸福愜意的狀態。"},coreKeyword:{en:"Comfort",zh:"舒適愜意"},meaning:{upright:{en:"Experiencing happiness as if in a dream / drawn toward joy created with another",zh:"如同置身夢境般感覺幸福/受到快樂吸引並享受其中"},reversed:{en:"Indulging in immediate pleasure / choosing comfort without accepting consequences",zh:"耽溺於眼前的快樂/只要現在好就好而不願負責"}},readingAspects:{currentSituation:{upright:{en:"A pleasant period / comfortable environment / a moment without worry / compatible rhythm / enjoying play / making a choice / hearts connecting",zh:"愉快的時期/舒適的環境/不會感到不安的時刻/調性契合/遊玩時能夠享受其中/選擇某事物的時候/心靈相通的狀況"},reversed:{en:"Fluctuating fortune / distracted and finding decision difficult / unresolved / fruitless period without reward / neglecting what matters",zh:"浮動的運氣/目光受吸引而難以決定/懸而未決/無論做什麼都無法獲得回報的徒勞時期/疏忽重要的事情"}},innerState:{upright:{en:"Great liking / fluttering heart / faint good feeling / wanting things to stay this way / absorbed in something / joy and happiness",zh:"最喜歡/內心悸動/隱約有好的感覺/想要一直這樣下去/熱衷於某種事物/萌生愛的喜悅或快樂"},reversed:{en:"Inner wavering / inability to choose / disgust at your pleasure-seeking self / lost motivation / temptation despite knowing it's wrong",zh:"內心動搖/無法抉擇/對快樂的自我感到嫌惡/對於一切失去幹勁/明知不行還是想伸出手的誘惑"}},rootCause:{upright:{en:"Only seeing what's in front of you / unable to consider future possibilities / unrealistic impossible plan / dangerously unprepared",zh:"只看得到眼前/無法考慮有何萬一的可能性/不符現實而不可能實現的計畫/過於沒有防備而危險"},reversed:{en:"Unaware of causing trouble / weak willpower and passive drift / unable to choose / shameful behavior / hopeless attraction",zh:"沒有意識到自己給人添了麻煩/意志薄弱而隨波逐流/做不出任何選擇/舉止丟臉/無可救藥地受到吸引"}},development:{upright:{en:"Joyful time that makes you forget time / sensory satisfaction / playful pure feeling / falling in love / easing anxiety / celebrating life",zh:"令人忘記時間的愉快時光/令五感都獲得滿足的事/以純粹的心情嬉鬧/愛上某個人/憂慮減緩/讚頌人生的時期"},reversed:{en:"Irresponsibly seeking pleasure / changing heart toward someone / dropped concentration and repeated mistakes / increasing complaints / tempting or being tempted",zh:"不負責任地只顧享樂/對某個人異心/專注力下降而連續出錯/牢騷滿腹的情緒增加/誘惑某人或受到誘惑"}},advice:{upright:{en:"Enjoy what's happening now / do not care about others' eyes / switch your mood cleanly / trust your heart when choosing",zh:"享受眼前發生的事/別在意他人的目光/乾脆地轉換心情/在做某些選擇時相信自己的內心"},reversed:{en:"Act with moderation / do not ignore surroundings for yourself / once decided, carry through / beware sudden wicked thoughts / control desire",zh:"採取行動要拿捏分寸/不要只想著自己而無視周遭/一旦決定後就要貫徹到底/要注意一時心生歹念/控制欲望"}}},contextualMeanings:{love:{upright:{en:"Falling in love / charming person / dreamlike romance / happy love / drawn to beauty or youth",zh:"墜入愛河/充滿魅力的人/如作夢般的戀情/快樂的戀情/被美貌或年輕吸引"},reversed:{en:"Love triangle / fickleness / casual love / promiscuity / mistakes / womanizing / romance without genuine love",zh:"三角關係/見異思遷/只是玩玩的戀愛/水性楊花/犯錯/好女色/沒有愛情的交往"}},work:{upright:{en:"Pleasant and focused work / sense of unity / successful negotiation / partnership / collaborative growth / clients",zh:"愉快且能專注的工作/連帶感/交涉成立/夥伴/共同開發/客戶"},reversed:{en:"Unable to focus / communication errors / temporary position / workplace unease / unexpected transfer / careless work",zh:"無法專注/聯絡出錯/暫時的工作/在工作上感覺不對勁/空降/粗率的作業"}},interpersonal:{upright:{en:"Engaging conversation / trust / light friendship / enjoyable and spirited atmosphere / someone you want to see again / inability to hate",zh:"相談甚歡/信任/輕便友善/氣氛愉快且熱烈/想再次見面的人/無法怨恨"},reversed:{en:"Incompatibility / being stood up / betrayal / well-intended trouble / fun but uneasy feeling",zh:"合不來/放鴿子/背叛/徒增麻煩的好意/雖然愉快卻總覺得哪裡不對勁"}},others:{upright:{en:"Win-win / playfulness / comfort / items that satisfy hobbies",zh:"雙贏/玩心/舒適/能滿足嗜好的物品"},reversed:{en:"Shame / bravado / bad habits / superficial conduct / unprofitable behavior",zh:"羞恥/逞強/壞習慣/敷衍、含糊/沒有獲益的行為"}}}},{id:"the-chariot",name:{en:"The Chariot",zh:"戰車"},arcana:"major",suit:null,number:7,description:{en:"A warrior rides a chariot drawn by black and white sphinxes. Controlling them requires strong will, power, and unwavering action toward the goal.",zh:"戰士搭乘戰車，定睛看著應前進的道路。黑白斯芬克斯象徵不同衝動，必須以堅強意志與力量控制，毫不猶豫地前進。"},coreKeyword:{en:"Victory",zh:"勝利"},meaning:{upright:{en:"Boldly confronting obstacles / advancing toward your goal with strong momentum",zh:"果敢地挑戰事物/朝著目標勇往直前"},reversed:{en:"Unable to control yourself / power spirals out of control and rushes in the wrong direction",zh:"無法自我控制/力量失控而朝錯誤方向前進"}},readingAspects:{currentSituation:{upright:{en:"Riding momentum / full of drive / time to act immediately / heading toward a new goal / power to overcome barriers / struggling with yourself",zh:"乘勢而行的運氣/幹勁十足/應該立刻採取行動的時候/朝向新目標/擁有跨越障礙的力量/與自己戰鬥的時候"},reversed:{en:"Situation spiraling out of control / hasty action without considering consequences / needing to choose direction / heading the wrong way / paralyzed by fear",zh:"狀況失去控制/不考慮後果就倉促行事/應該選擇前進方向的狀況/朝著錯誤方向前進/因為恐懼而無法出發"}},innerState:{upright:{en:"Acting from conviction / unwilling to drag things out / wanting to express yourself / eager to try something new / determined to succeed / defeat is impossible",zh:"基於信念採取行動/不想拖拖拉拉/想傳達自己的想法/想挑戰全新的事物/想要成功/絕對不可能落敗"},reversed:{en:"Illogical thoughts / worry about starting too late / excessive competitive drive / melancholy about the future / confusion about direction",zh:"想法不合邏輯/擔心自己起步過晚/不想認輸的過剩爭鬥心/一想到未來就憂鬱/對前進方向感到迷惘"}},rootCause:{upright:{en:"Development moving too quickly / combative attitude causing unnecessary conflict / major change ahead / unable to demonstrate leadership",zh:"進展過於急促/好戰態度導致不必要的麻煩/面臨重大改革/無法發揮領導能力"},reversed:{en:"Important decisions delayed / beginning without a solid plan / self-centered disregard for surroundings / panic following setback",zh:"延後重要選擇/在沒有確實計畫的情況下展開/不顧周遭的任性態度/受到打擊而驚慌失措"}},development:{upright:{en:"Rapid advancement / smooth success / entrusted with new responsibility / rising prominence / decisive victory / experience sharpens you",zh:"發展迅速/一帆風順地成功/被交付開拓新領域的工作/乘勢提升名氣/漂亮地獲勝/以經驗磨練"},reversed:{en:"Severe conflict from disagreement / painful position / risky gamble / forced interruption / defeat / stalemate",zh:"意見不合引發激烈衝突/被迫面臨痛苦立場/涉入危險賭注/不得不中斷/敗戰/進退維谷"}},advice:{upright:{en:"Show more courage / become the leader / once started, advance with full force / victory is likely if you fight / overcome your weakness",zh:"多拿出點勇氣/你應該成為領導者/一旦著手就要一口氣前進/只要迎戰就有十足勝算/克服自身軟弱"},reversed:{en:"Review your plan before failure / do not force progress / pause and change course / manage your emotions / look around and assess the situation",zh:"這樣下去可能會失敗，應重新審視計畫/不要勉強前進/一度停下，變更路線/控制情緒/環顧周遭判斷狀況"}}},contextualMeanings:{love:{upright:{en:"Closing the distance actively / overcoming obstacles together / energetic person / vitality and passion",zh:"一口氣前進/積極拉近距離/克服障礙/生氣勃勃的人"},reversed:{en:"Hurting each other / constant conflict / impatient person / losing to a rival / runaway thoughts",zh:"互相傷害的關係/吵個不停/性急的人/輸給情敵/想法失控"}},work:{upright:{en:"Facing challenges / successful presentation or proposal / gaining position / defeating competitors",zh:"面對任務/簡報或企劃通過/贏得地位/贏過競爭對手"},reversed:{en:"Plan fails / defeat / stolen ideas / mistakes / standing at a crossroads / giving up halfway",zh:"企劃落空/落敗/企劃被搶/失誤/站在分岔路口/半途而廢"}},interpersonal:{upright:{en:"Good momentum / energetic person / constructive and active relationship / action-oriented approach",zh:"步調很合/活力十足的人/具建設性的關係/積極的關係/有行動性"},reversed:{en:"Disagreement / conflict / relationship stalls / nothing gets resolved / recklessness / mischief",zh:"意見不合/衝突/關係沒有發展性/什麼也沒有解決/得意忘形/惡作劇"}},others:{upright:{en:"Busyness / spirited energy / rapid advancement / will to win / courage / powerful force / travel / movement / motion",zh:"忙碌/精神飽滿/迅速前進/獲勝意志/堅強勇氣/力量強勁/旅行/移動/奔跑"},reversed:{en:"Fatigue increasing / cannot decide / no progress / difficult troubles / defeat / stagnation",zh:"疲勞感加重/無法下決定/沒有前進/棘手的麻煩/落敗/止步不前/延遲"}}}},{id:"strength",name:{en:"Strength",zh:"力量"},arcana:"major",suit:null,number:8,description:{en:"A gentle woman softly touches the jaw of a fierce lion. This card represents not physical force, but the inner strength of love, patience, and mutual understanding.",zh:"纖細的女子伸手撫摸凶猛獅子的下頜。這張牌所意味的力量不是臂力或權力，而是愛、耐心與心靈相通的內在力量。"},coreKeyword:{en:"Essential strength",zh:"本質上的力量"},meaning:{upright:{en:"Overcoming difficulty / moving another through love, patience, and sincerity",zh:"跨越困難/靠愛與耐心打動對方"},reversed:{en:"Unable to endure and letting go / losing patience before reaching the end",zh:"難以忍耐而撒手不管/無法堅持到最後"}},readingAspects:{currentSituation:{upright:{en:"Critical moment / must face a beast-like person or situation / requires careful action / turning danger into opportunity",zh:"關鍵時刻/不得不面對如猛獸般的人物或狀況/需要謹慎且周全地採取行動/能化危機為轉機"},reversed:{en:"Declining fortune / having to give something up / your inner strength is being tested / wanting to abandon everything / near collapse",zh:"運勢衰退/不得不對某些事物死心斷念/精神力的強韌度遭到質疑/試圖拋下一切/瀕臨崩潰邊緣"}},innerState:{upright:{en:"Not wanting it to end / determined to hold on / confidence in winning over the other / seeking reconciliation / finding a new path forward",zh:"不想讓事情就這樣結束/想撐到最後/相信能夠籠絡對方的自信/想與對方和解/想設法開創新路並獲得成果"},reversed:{en:"Losing passion / everything seems fine now / refusing to admit defeat / trying to manipulate someone / reckless responses",zh:"失去熱情而覺得怎樣都好/無法對變化作出應對/在心情上認輸/試圖諂媚以籠絡某人/貿然應對"}},rootCause:{upright:{en:"Voluntarily shouldering hardship / challenging a high bar / accumulated strain / opponent is unexpectedly difficult / misjudging your approach",zh:"主動肩負辛勞/挑戰過高的門檻/累積壓力/對手出乎意料地棘手/力度拿捏出錯"},reversed:{en:"Losing to your own weakness / giving up with that's enough / insufficient mental and physical reserves / persistent effort fails / misguided manipulation exposed",zh:"敗給自己的軟弱/認為受夠了而放棄/精神與肉體力量不足/堅持努力無法奏效/試圖利用對方卻被看穿"}},development:{upright:{en:"Overcoming tension / converting enemies into allies / receiving support from companions / finding strong backing / overcoming flaws and weaknesses",zh:"克服充滿緊張感的狀況/化敵為友/獲得同伴協助/找到強力後盾/克服缺點或弱點"},reversed:{en:"Giving up at the final step / lowering your standards / careless mistakes once you relax / excessive warmth backfires / passion for dreams declines",zh:"在最後一步認輸/降低堅持標準/一鬆懈就出錯/過分熱絡造成反效果/朝夢想邁進的熱情減退"}},advice:{upright:{en:"Do not give up after coming this far / crisis is opportunity / create a battle plan / seek helpers / victory is near with one more push",zh:"已經努力到這一步，不要放棄/危機就是轉機/確實擬定作戰計畫/尋求協助者/只要加把勁，勝利就在眼前"},reversed:{en:"Accept it if your heart has cooled / shake off cowardice / do not force yourself / ask for help / do not forget gentle words and consideration",zh:"如果情緒已經冷卻就放棄/揮去膽怯/不要逞強，向人求助/不要忘記溫柔的話語或體貼"}}},contextualMeanings:{love:{upright:{en:"Strong bond / love built over time / considerate and patient relationship / person with strong conviction",zh:"締結穩固羈絆/累積時間成就的戀情/體貼與忍耐的關係/有堅強意志的人"},reversed:{en:"Difficult romance / wanting to give up / concerned about being disliked / need for careful navigation",zh:"棘手的戀情/想要放棄的愛情/在意受到討厭/需要察言觀色的對象"}},work:{upright:{en:"Will definitely complete / reaching high goals / long-term project / good partner or sponsor / thoughtful support",zh:"一定會完成/達成很高目標/長期案件/好的夥伴或贊助商/應對撫慰"},reversed:{en:"Insufficient perseverance / unable to continue work / cannot maintain focus / lacking coordination / empty ambition",zh:"毅力不足/無法持續工作/無法專心/沒有協調性/空有野心"}},interpersonal:{upright:{en:"Mutual support / relationship of trust / reliable person / worthy opponent / mature exchange",zh:"互相協助的關係/信任關係/可靠的人/可敬的對手/成熟的應對"},reversed:{en:"Self-righteousness / self-centeredness / unable to cooperate / petty gains / trying to please others / willfulness",zh:"自命清高/自我中心/無法合作/小利/討人歡心/任性"}},others:{upright:{en:"Positive effort / cooperation / indomitable spirit / synchronized pace / turning adversity into aid / precise control",zh:"積極正向/努力合作/不屈不撓精神/步調一致/將逆境化為助力/拿捏力度"},reversed:{en:"Negativity / escape / scattered state / submission to force / defeat / need for patience",zh:"消極/逃避/七零八落/屈服於力量/落敗/需要忍耐"}}}},{id:"the-hermit",name:{en:"The Hermit",zh:"隱士"},arcana:"major",suit:null,number:9,description:{en:"An old man in a grey robe stands alone with a lantern. He withdraws from the world to face his inner truth and seek wisdom from past experience.",zh:"老人身披灰色長袍，獨自佇立，手中提燈閃耀六芒星光芒。他遠離塵世，面對內心世界，從過去經驗中探求真理。"},coreKeyword:{en:"Inquiry",zh:"探究"},meaning:{upright:{en:"Seeking ideals / quietly examining your inner world and gaining wisdom",zh:"追求理想/平靜地審視內心並獲得智慧"},reversed:{en:"Not facing reality / clinging to past glory and withdrawing from the world",zh:"不正視現實/緊抓過去榮耀而封閉自己"}},readingAspects:{currentSituation:{upright:{en:"Fortune that maintains the present / stable with little fluctuation / neither clearly good nor bad / time for learning / seeking solitude",zh:"維持現狀的運氣/起伏不大的平穩狀況/無論好壞都沒有變化/學習的時候/想減少與人交流而獨處的時候"},reversed:{en:"Confronting your former self / dwelling in nostalgia / stalled and incomplete / isolated from the world",zh:"面對過去的自己的時候/沉溺於那個時候比較好的想法/事情停滯，虎頭蛇尾/與世隔絕的狀況"}},innerState:{upright:{en:"Clear boundaries between yourself and others / wanting to learn / seeking alone time / examining your inner self / thoughts misunderstood even when voiced",zh:"明確區分別人是別人，自己是自己/想要學習些什麼/想要獨處的時間/想審視自己的內心/即使說了也不被理解的想法"},reversed:{en:"Concerned with appearance / living in memories / not admitting true feelings / unspeakable loneliness",zh:"在意面子/住在回憶裡/不打算承認真正的心情/心生難以言喻的寂寞或孤獨感"}},rootCause:{upright:{en:"Excessive fixation / knowledge or experience underutilized / extreme interests / overthinking / antisocial tendencies",zh:"過度拘泥/空有知識或經驗卻無法充分活用/興趣過於偏激/想太多而鑽牛角尖/討厭社交的氛圍"},reversed:{en:"Distorted thinking / surface-level learning / immersed in your own world / over-idealizing interests or people / escaping reality",zh:"想法錯誤/總是現學現賣/沉浸在自己的世界裡/將喜歡的事物或人過於理想化/逃避現實"}},development:{upright:{en:"Stable days continue / no visible progress / confusion settles / someone to consult appears / journey of self-discovery",zh:"平穩的日子持續/看不到事態進展，維持現狀/混亂平息/出現商量對象/邁向追尋自我的旅程"},reversed:{en:"Missing the timing to step outside / unable to face reality / closed attitude / reconnecting with figures from your past / retrying past failures",zh:"錯失踏出外界的時機/無法正視現實/態度封閉/與過去有緣的人重新建立關係/再次挑戰曾失敗的事物"}},advice:{upright:{en:"Do not rush / take time to face things / do not carry it alone / consult someone / hints lie in similar past situations",zh:"不要焦急，應該花時間面對/不要獨自承擔，找人商量/需要再好好思考/過去類似狀況中藏有提示"},reversed:{en:"Stop making excuses about the past / sometimes giving up is necessary / realize no one will help if you keep waiting / climb by your own power",zh:"不要再找藉口說都是因為那時候/放棄也是必要的/察覺即使等待也沒人會來幫忙/靠自己的力量爬上來"}}},contextualMeanings:{love:{upright:{en:"Long-hidden secret love / older partner / quiet stability / relationship bringing spiritual growth",zh:"長年隱藏在心裡的戀情/年長的對象/莫名穩重的人/帶來精神成長的關係"},reversed:{en:"Drawn to the feeling of romance / fantasy romance / seeking romance / rediscovering love's beauty",zh:"愛上戀愛的感覺/脫離現實的妄想戀情/尋求戀情/重新認識戀愛的美好"}},work:{upright:{en:"Spiritually fulfilling / mentoring subordinates / experienced seniority / long-term specialty / research work",zh:"精神上很充實/率領部下/資深人員/經驗/長年持續/專業職務/研究職務"},reversed:{en:"Ignoring sound advice / unsuited to society / unemployed / dismissive due to pride",zh:"無視正經意見/不適應社會/無業/因為自尊心而瞧不起人"}},interpersonal:{upright:{en:"Unchanging relationship / consultation partner / long association / old acquaintance / learned homebody companion",zh:"不變的關係/商量對象/綿長交往/舊識/學識淵博/宅夥伴"},reversed:{en:"Difficult to please / cautious relationship / introverted personality / unpleasant even when meeting",zh:"難以取悅的對象/必須小心的關係/性格內向/即使見面也不愉快"}},others:{upright:{en:"Conviction / carrying through ideals / good but not popular / expertise",zh:"擁有信念/貫徹想做的事到底/雖是好事卻不受大眾接受/專業知識"},reversed:{en:"Needs no one / lacking conviction / excessive persistence / preoccupied with others' opinions",zh:"不需要任何人/沒有信念/過剩的堅持/在意他人目光"}}}},{id:"wheel-of-fortune",name:{en:"Wheel of Fortune",zh:"命運之輪"},arcana:"major",suit:null,number:10,description:{en:"The giant wheel turns slowly, surrounded by symbolic beings. All life exists within an inescapable current where one may rise or fall.",zh:"緩緩轉動的巨大車輪代表命運。所有生命都身處無法逃脫的洪流之中，可能上浮，也可能下沉。"},coreKeyword:{en:"Destiny",zh:"命中註定"},meaning:{upright:{en:"Events improve through fate's flow / unexpected chances appear and must be seized quickly",zh:"事態因命運的洪流而好轉/意料之外的機會造訪，必須迅速掌握"},reversed:{en:"Being toyed with by fate / things deteriorate, chances are wasted, and confusion mounts",zh:"被命運玩弄於股掌之間/不順遂、浪費機會而筋疲力竭"}},readingAspects:{currentSituation:{upright:{en:"Fortune becoming smoother / luck improving / fortunate coincidences / pleasant developments / stalled matters suddenly moving / destiny's crossroads",zh:"越發一帆風順的運氣/運氣好轉/偶然重疊的幸運/令人高興的情況/停滯的事情突然開始推進/命運的岔路"},reversed:{en:"Everything in vain / the same patterns repeat without progress / fortune sinking while panicking / toyed with by unexpected change / sudden misfortune",zh:"一切徒勞無功/同樣事情一再發生毫無進展/運氣在驚慌期間下沉/遭到出乎意料的變化玩弄/毫無前兆的厄運"}},innerState:{upright:{en:"Intuitively finding the right answer / believing in destiny / adaptable to anything / enjoying unpredictability",zh:"直覺地找出正確答案/確信這是命運/無論發生任何事都能臨機應變/享受無法預測的事態"},reversed:{en:"Discouraged by why this happened despite doing nothing wrong / no answers / at a loss / ominous situation / contradictory feelings",zh:"明明應該沒出錯，為什麼會這樣而氣餒/無法得出答案/為眼前狀況不知所措/感覺情勢險惡/矛盾情感"}},rootCause:{upright:{en:"Expecting too much luck / resisting the natural flow / going with the flow while neglecting effort / stubborn mindset",zh:"過於期待幸運/抵抗自然流勢/只是順其自然而懈怠努力/過於死心眼"},reversed:{en:"Not noticing the backlash / fearing change and clinging to the present / trying to control everything alone",zh:"沒有發現適得其反/畏懼變化而緊抓現狀不放/試圖靠自己掌控一切"}},development:{upright:{en:"Good luck arrives / oddly fortunate / everything flows smoothly / perfect timing / meeting the person you want / right answers emerge",zh:"好運到來/莫名地走運/所做的事情一切順利進行/時機很巧/見到想見的人物/得出正確答案"},reversed:{en:"Suddenly disadvantaged / being swept up / inescapable disaster / cornered by failure / losing a wager",zh:"眨眼間面臨不利形勢/受到連累/遇上無法逃脫的災難/因失敗而把自己逼上絕境/打賭輸了"}},advice:{upright:{en:"The answer that flashes naturally is correct / respond to circumstances rather than forcing action / seize the chance / trust that everything connects",zh:"直覺地在腦中閃現的答案就是正確答案/與其主動行動不如順應局勢/不要躊躇，把握機會/相信一切都會連接起來"},reversed:{en:"Do not volunteer blindly / use smart strategy / set aside pride and stubbornness / borrow luck and others' strength",zh:"不要自告奮勇/採取聰明策略/捨棄意氣用事或自尊心/與其孤軍奮戰，不如借助運勢或周遭力量"}}},contextualMeanings:{love:{upright:{en:"Fated encounter / love at first sight / compatible partner / marriage / love carried by momentum",zh:"感受到命運的邂逅/一見鍾情/意氣投合的對象/結婚/順勢的戀愛"},reversed:{en:"Fleeting kindness / repeated bad timing / mismatched values / missed romance / thrilling but unstable love",zh:"短暫的恩情/接二連三的不湊巧/價值觀不合/錯過的戀情/驚心動魄的愛情"}},work:{upright:{en:"Grasping all opportunities / favorable flow / sharp intuition / support / excellent condition",zh:"掌握住一切機會/流勢很好/第六感很準/受到提拔/狀態絕佳"},reversed:{en:"Forced to handle unsuitable matters / unable to complete smoothly / effort still fails / futile efforts",zh:"被迫處理不擅長的事/無法順利完成/即使努力也辦不到/徒勞無功"}},interpersonal:{upright:{en:"Pleasant person / natural compatibility / soul mate / memorable first impression",zh:"感覺很好的人/聊得來/自然而然合得來/靈魂伴侶/初次見面印象深刻"},reversed:{en:"Awkward conversation / boring / bad contact timing / naturally drifting away / unsuitable person",zh:"不協調/對話很無趣/聯絡時機很糟/自然而然疏遠/不合時宜的人物"}},others:{upright:{en:"Fated development / interesting / captivating / timely impression",zh:"命運般的發展/有趣/感興趣/靈光一閃/適時印象深刻的事"},reversed:{en:"Boring / wrong timing / forgotten in memory / missed opportunity / outdated",zh:"無趣/時機不對/遺忘在記憶中/錯過好機會/落伍"}}}},{id:"justice",name:{en:"Justice",zh:"正義"},arcana:"major",suit:null,number:11,description:{en:"A calm judge sits with scales and sword, objectively weighing cause and effect. This card shows fairness, judgment, and balance without emotional interference.",zh:"英氣凜然的中性女子端坐中央，以天秤衡量罪行輕重，並以劍制裁。這張牌暗示不受情感操弄，客觀公正地判斷。"},coreKeyword:{en:"Balance",zh:"平衡"},meaning:{upright:{en:"Responding calmly without emotion / facts receive fair evaluation",zh:"不夾雜情感地冷靜應對/事實合理地獲得正當評價"},reversed:{en:"Swayed by emotion and responding unfairly / imbalance and unjust treatment",zh:"受到情感左右而採取不合理的應對/失衡與不公平"}},readingAspects:{currentSituation:{upright:{en:"Luck cannot be forced / only facts matter, not emotions / results caused by your past actions / cannot support either side / injustice is judged",zh:"只靠運氣無法推進/不夾帶情感只考慮事實/過去的自己造成的結果/無法支持任何一方/不正當的事物受到制裁"},reversed:{en:"Cannot overcome by logic alone / past wrongdoing is blamed / unjust treatment / imbalance between effort and reward / accepting necessary compromise",zh:"無法靠常識克服/過去不正當行徑遭譴責/受到不公平對待/付出與報酬失衡/認同必要之惡"}},innerState:{upright:{en:"Prioritizing facts over feelings / without supporters / overlooking no falsehoods / unwilling to do wrong / dissatisfied with disorder",zh:"比起情感更想以事實為優先/沒有任何人支持/微小謊言也不放過/不打算做虧心事/對條理不分明感到不滿"},reversed:{en:"Anger at perceived wrongness / desperately defending yourself / believing tears bring forgiveness / feeling guilty",zh:"對某人產生這是不對的憤怒/為自保拚命辯解/認為哭求就能獲得原諒/感到內疚"}},rootCause:{upright:{en:"Judging only by right and wrong / no consideration / too strict and humorless / intimidating others",zh:"判斷時只以正確與否為基準/毫不體貼/過於嚴格而沒有幽默感/令周遭生畏"},reversed:{en:"Calculating conveniently / complaining without action / drawn to distorted ideas / arbitrary behavior / guilt",zh:"打著如意算盤/只是滿腹牢騷而不行動/傾心於扭曲思想/獨斷行動令周遭不願跟隨/罪惡感"}},development:{upright:{en:"Facing reality / carrying through what is right / situation becomes favorable / past actions bring benefits / effort is rewarded",zh:"面對現實/貫徹自認為正確的事/狀況逐漸有利/受到過去行為恩惠/努力獲得回報"},reversed:{en:"Unreasonable circumstances / rights violated / one-sided exploitation / relationship collapse / paying for past injustice",zh:"面臨不合理事態/權利受到侵害/單方面受到壓榨/關係失衡/因過去不公不義付出代價"}},advice:{upright:{en:"Judge by facts, not emotion / organize the problem / think constructively / do not violate ethics",zh:"不以情感判斷，只著眼於事實/將問題好好整理/建設性地思考接下來該怎麼做/切勿違反倫理道德"},reversed:{en:"Give up convenience-based thinking / notice your disadvantage / stop enduring everything / restore balance",zh:"放棄只圖自己方便的思考方式/察覺自己正被逼到不利處境/別再逆來順受/取回平衡"}}},contextualMeanings:{love:{upright:{en:"Equal partnership / suitable partner / balanced terms / neither liking nor disliking",zh:"對等的情人關係/合適的對象/條件相稱/不喜歡也不討厭的對象"},reversed:{en:"Calculated romance / hedging bets / assessing the other's value",zh:"打如意算盤的交往/騎驢找馬/評估對方的價值"}},work:{upright:{en:"Proper compensation and evaluation / suitable outcome / work-life balance / assuming responsibility",zh:"正當的報酬或評價/得到相稱結果/事業生活兩得意/肩負責任"},reversed:{en:"Unreasonable pay or treatment / unfair workplace / making excuses / doing only what you like / taking credit",zh:"報酬與待遇不合理/不公平職場/藉口/只做喜歡的工作/覬覦別人功勞"}},interpersonal:{upright:{en:"Mutually beneficial / no personal feelings / businesslike approach / neutral person / equality",zh:"互惠互利的關係/不夾帶私情/公事公辦/中立的人/平等"},reversed:{en:"Profit-first relationship / someone who uses people / biased thinking / superficial and emotional",zh:"以利益為優先的關係/利用人的人/偏頗思考/半吊子且夾帶私情"}},others:{upright:{en:"Draw / comparison / measured wording / ethics / legal action / judgment / analytical thinking",zh:"平手/比較/冷靜的措辭/倫理道德/採取法律措施/審判/理論性的思考"},reversed:{en:"Changes from imbalance / self-righteous justice / falsehood / forgery",zh:"失衡而引發的變化/自命清高的正義感/虛假/造假"}}}},{id:"the-hanged-man",name:{en:"The Hanged Man",zh:"吊人"},arcana:"major",suit:null,number:12,description:{en:"A man hangs upside down from a tree, yet his expression is peaceful and his head glows. Because his body cannot move, his thoughts become clearer.",zh:"男性雙手被反綁，單腳吊掛在樹上，但表情平靜，頭後散發光芒。正因手腳無法動彈，思考反而更加通透。"},coreKeyword:{en:"Stillness",zh:"靜止"},meaning:{upright:{en:"Facing your situation and thinking clearly / accepting what cannot be changed",zh:"面對現況冷靜思考/承認現實上的不如意"},reversed:{en:"Unable to accept your state and struggling / suffering increases through resistance",zh:"無法接受現況而掙扎/越焦急抵抗越痛苦"}},readingAspects:{currentSituation:{upright:{en:"Helpless from your own perspective / unable to move under someone's control / time spent alone / forced pause / witnessing your powerlessness",zh:"憑一己之見無可奈何/在某人的處理之下動彈不得/獨自度過的時候/強制停止/親眼目睹自己的無力"},reversed:{en:"Trying to escape pain but suffering through struggle / resistance is futile / forced to start over / made an example of",zh:"試圖逃離痛苦卻因掙扎而受苦/即使拚命抵抗也無計可施/被迫重來某些事/被當成殺雞儆猴的對象"}},innerState:{upright:{en:"Resolve / endurance / accepting pain / impatience / understanding limits / accepting you can only stay here",zh:"要有覺悟/忍耐/忍受痛苦/感覺著急/明白自己的極限/認清只能待在此處而放棄"},reversed:{en:"Cannot prepare mentally / wanting to escape if possible / cannot accept limitations / wanting to abandon everything / self-sacrifice",zh:"無法做好覺悟/如果逃得掉很想逃跑/無法承認自己的極限/想拋下一切/為了他人而犧牲自己"}},rootCause:{upright:{en:"Spiritual and physical limitations / too exhausted to think clearly / passive approach / resisting reality and freezing / lack of support",zh:"精神上、肉體上的極限/過於疲倦而無法冷靜思考/被動態度/抗拒現實而停止思考/沒有後援的環境"},reversed:{en:"Desperate struggle / pushing hard regardless of circumstances / only thinking of yourself / indecisive hesitation / stressful environment",zh:"死命掙扎/過於拚命而不顧一切/只考慮自己/無法下定決心的半吊子態度/受到壓力的環境"}},development:{upright:{en:"Forced endurance / facing yourself / becoming support for others / finding a new self through deep struggle / overcoming obstacles",zh:"被迫忍耐的發展/面對自己/轉而擔任支援他人的工作/歷經重大煩惱後產生全新的自己/克服"},reversed:{en:"Mounting pain / emotional outburst from inability to endure / rash actions from fear / losing what matters / impatient progression",zh:"痛苦增加/無法承受而爆發情緒/出於恐懼或不安採取錯誤行動/失去重要事物/令人著急的發展"}},advice:{upright:{en:"Accept everything and wait for time to pass / calm thinking reveals the path forward / filter out external voices to find new insights",zh:"接受一切，等待時間過去/藉由冷靜思考就能看見光明/隔絕局外人的聲音，就能發現新的靈感"},reversed:{en:"You may feel relief the moment you accept your powerlessness / sometimes doing nothing brings better results / recognize your unhelpful thought patterns",zh:"承認自己的無力的瞬間會感到輕鬆/與其掙扎，不如什麼都不做，反而能得到好結果/意識到自己思考上的壞習慣"}}},contextualMeanings:{love:{upright:{en:"No visible progress / needs time / devoted romance / better to give the other space",zh:"沒有進展/需要時間/奉獻型戀情/讓對方獨處比較好"},reversed:{en:"Painful romance to endure / endless unrequited love / self-centered attachment / obsession",zh:"痛苦而忍受的戀情/看不見終點的單戀/自我中心的戀慕心/執著於某個人"}},work:{upright:{en:"Overloaded / mentally and physically drained / unpaid effort / facing a trial / unwavering dedication",zh:"超出負荷/消耗身心能量/不求回報/迎向考驗/一個勁兒地奉獻"},reversed:{en:"Always seeking returns / retreating from reality / claiming rights",zh:"在意回報/總想逃離現實/拘泥於自己的權利"}},interpersonal:{upright:{en:"Becoming isolated / desiring solitude / organizing your thoughts / enduring unavoidable people",zh:"變得孤獨/想要獨處/整理自己的想法/忍耐/拿他沒有辦法的對象"},reversed:{en:"Troublesome person / shrinking away / causing disturbance / affecting composure",zh:"造成困擾的人/萎縮/引發騷動/故作成熟地假裝平靜"}},others:{upright:{en:"Spirit of sacrifice / difficult circumstances / proactive spirit / self-discipline / acceptance and introspection / pause",zh:"犧牲的精神/狀況不佳/具積極進取精神/嚴以律己/接受並反省/停止"},reversed:{en:"Self-harm / impatience / inescapable suffering / inability to accept everything / unbearable loneliness / desperate struggle",zh:"自虐/著急/無法逃離的痛苦/無法接受一切/難以忍受孤獨一人/死命掙扎"}}}},{id:"death",name:{en:"Death",zh:"死神"},arcana:"major",suit:null,number:13,description:{en:"Death rides a white horse across the battlefield as the sun rises in the distance. This represents not only an end, but also rebirth and movement to a new stage.",zh:"死神騎乘白馬靜靜前進，遠方太陽緩緩升起。這張牌呈現終結與起始，暗示精神、人際關係或環境的煥然一新。"},coreKeyword:{en:"Fixed fate",zh:"定數"},meaning:{upright:{en:"Moving to a new stage / accepting an ending and embracing new beginnings",zh:"前往新的階段/接受終結並迎向新生"},reversed:{en:"Bound by the past and unable to progress / clinging to the current state prolongs suffering",zh:"受到過去束縛而無法前進/戀棧現狀使痛苦延長"}},readingAspects:{currentSituation:{upright:{en:"Something reaches an end / separation from an important person / moving to the next stage / life-changing moment / ongoing transformation",zh:"某種事物面臨終結/歷經與重要的人別離/前往下一個階段/改變人生的時機/持續變化"},reversed:{en:"Stagnation / fluctuating fortune / unable to adapt to changing circumstances / trying to delay the inevitable / emotions in disarray / unacceptable ending",zh:"停滯不前/運氣忽好忽壞/跟不上逐漸改變的情勢/試圖拖延結束/無法整理情緒/無法接受的結局"}},innerState:{upright:{en:"Decision made / inner conclusion reached / letting go of attachments / bittersweet choice / acceptance / refreshed feeling / already facing the future",zh:"下定決心/內心已有定見/放下原本執著的事物/苦澀的選擇/斷念/心情舒暢/心情已邁向未來"},reversed:{en:"Refusing to let go / clinging / unable to decide / seeking revival / incomplete state / inner wound / sentimental",zh:"不肯輕易死心/依戀不捨而無法放棄/無法下定決心/企圖起死回生/半途而廢的狀態/內心創傷/多愁善感"}},rootCause:{upright:{en:"Extreme black-and-white thinking / too sudden to prepare mentally / natural consequence with no clear cause / all is destiny",zh:"思考方式極端，非黑即白/過於突然而無法做好心理準備/理所當然的結果，沒有明確原因/一切都是天命所定"},reversed:{en:"Overwhelming shock / unable to face the present / lacking courage to decide / memories resurface repeatedly / unable to move forward",zh:"過大的驚嚇/無法好好正視現狀/下定決心的勇氣不足/記憶一再復甦/無法前進"}},development:{upright:{en:"Rebirth / relationships or situations forcibly reset / generational shift / sudden change transforms life / irresistible events",zh:"重獲新生/關係或狀況被強制重來/世代交替或新舊更迭/突然變化使生活大為轉變/不可抗力事件"},reversed:{en:"Extended duration / unable to change methods / overstaying and annoying others / forced to give up / unable to sever ties / unable to see present clearly",zh:"操勞延長/無法改變做法/長時間賴著不走令人厭煩/不得不放棄/遲遲無法斷絕/無法認清現況"}},advice:{upright:{en:"End decisively / the courage to stop matters / start fresh as if reborn / believe something new is beginning",zh:"果斷地重來/停損的勇氣也很重要/以脫胎換骨的心情重新開始/相信某種新的事物將要開始"},reversed:{en:"Face what you have avoided / do not waste time / decide now / do not expect miraculous chances / recognize necessity",zh:"面對一直逃避的事物/不要浪費時間/現在就下決定/不要期待奇蹟般的機會/認清究竟有沒有必要"}}},contextualMeanings:{love:{upright:{en:"The one / confession / settling the past / rekindled romance / marriage decision / remarriage",zh:"認為就是這個人的對象/表白/整理過去/戀情復燃/決心結婚/再婚"},reversed:{en:"Unrequited romance / awkward confession / secret love / unresolved matters / romantic regrets",zh:"戀情沒有結果/尷尬的表白/暗戀/事情沒有做個了斷/戀情上的懊悔"}},work:{upright:{en:"Comeback opportunity / restoring reputation / returning to your original purpose / relief / charting a new direction / success",zh:"起死回生的機會/洗刷污名/回歸初衷/放下心中的大石頭/決定導向成功"},reversed:{en:"Unrewarded effort / missed opportunity / setbacks / extended difficult work",zh:"沒有回報的努力/錯失機會/遇到挫折/辛苦的工作延長"}},interpersonal:{upright:{en:"Settling the relationship / decisive moment / reunion / repairing ties / important person to get to know",zh:"把關係做個了斷/一決勝負時/重逢/修復關係/應該事先掌握的重要人物"},reversed:{en:"Gradual distance / fading presence / hard to repair bonds / impossible reunion / troublesome person",zh:"逐漸疏遠/忘記其存在/關係難以修復/無法重逢/麻煩的人物"}},others:{upright:{en:"Favorable momentum at the turning point / finding the right approach / sharp intuition / regaining good fortune / decisive action",zh:"一決勝負時有利的運勢/找到訣竅/直覺敏銳/恢復好運/乾脆果斷"},reversed:{en:"Disadvantage at the crucial moment / cannot find the right approach / postponed decisions / insufficient preparation / expired",zh:"一決勝負時居於劣勢/找不到訣竅/決定延期/準備不足而無法行動/過期"}}}},{id:"temperance",name:{en:"Temperance",zh:"節制"},arcana:"major",suit:null,number:14,description:{en:"An angel skillfully pours water between two cups, as if suggesting communication. This card emphasizes mixing, adjustment, and the new results born from different elements meeting.",zh:"天使靈巧地操控兩個杯子裡的水，像是在暗示溝通。這張牌強調混合、調整，以及不同事物接觸後產生的新反應。"},coreKeyword:{en:"Reaction",zh:"反應"},meaning:{upright:{en:"Accepting new things / opening your heart and adapting to different perspectives and values",zh:"接受全新事物/敞開心胸並理解不同意見或價值觀"},reversed:{en:"Unable to accept different things / rejecting others' input and causing friction",zh:"無法接受性質相異的事物/拒絕意見而造成不協調"}},readingAspects:{currentSituation:{upright:{en:"Things need adjusting / discovering something through exchange / favorable chemistry / integration and reorganization / new realization / just right",zh:"應該調整事物/從與他人的交流中察覺些什麼/產生好的化學變化/整合與重組/有新的發現/剛剛好"},reversed:{en:"Uncoordinated fortune / resistance to meeting people / repeated near misses / incompatible environment / frequent conflicts",zh:"不協調的運氣/對與人見面表示抗拒/各方面經常錯身而過/置身格格不入的環境/衝突很多"}},innerState:{upright:{en:"Open-minded and genuine / hoping others open up too / seeking mutual understanding / wanting multiple perspectives",zh:"敞開心胸，非常坦率/希望對方也能敞開心房/想要互相理解/想參考許多人的意見"},reversed:{en:"Appearing to accept but not really listening / overthinking and overcomplicating / forcing your own method / lack of flexibility",zh:"看似接納別人的意見，其實沒有在聽/鑽牛角尖而搞得複雜/試圖強行貫徹自己的做法/沒有彈性"}},rootCause:{upright:{en:"Too concerned with others' opinions / overly interested in many things without results / honest nature making responses difficult",zh:"凡事都太過在乎別人的意見/對許多事過度感興趣卻無疾而終/因為老實而苦於應對周遭"},reversed:{en:"No connection / lack of communication / assuming unspoken understanding / shallow comprehension / incompatibility",zh:"各方面都沒有連結/溝通不足/自認為不說出口也能明白/對對方理解淺薄/不契合"}},development:{upright:{en:"Integrating complexity into harmony / bringing new atmosphere to life / meeting culturally different person / tempering excesses",zh:"將複雜事物整合為一/為生活帶來新氣象/與帶來文化衝擊的對象相遇/調整過度的事物"},reversed:{en:"Indigestion / wandering without grasping chances / disappointing outcome / excessive rejection / disordered life and health decline",zh:"消化不良/走來走去無法把握機會/期待落空/對他人的拒絕反應過強/生活紊亂搞壞身體"}},advice:{upright:{en:"Aim for the just-right balance / reconcile conflicting inner feelings / find situation-appropriate methods / think of compromises",zh:"以剛剛好的狀態為目標/與自己內心的不同情感和解/找出因應狀況的做法/思考折衷方案"},reversed:{en:"Do not deny anything or anyone / stay interested / continue dialogue to understand / do not retreat into your ivory tower",zh:"不要對任何事物或人持否定態度，抱持興趣/一再對話以理解對方/不要縮在自己的象牙塔裡"}}},contextualMeanings:{love:{upright:{en:"Romance progresses smoothly / caring for the other / compatible in body and spirit / understandable partner / attracted by wisdom",zh:"戀情進展順利/關心對方/身心都合得來/能夠理解的情人/被智慧吸引"},reversed:{en:"Romance makes no progress / toying with the other / always self-prioritizing relationships",zh:"戀情遲遲沒有進展/將對方耍著玩/總是以自己為優先的關係"}},work:{upright:{en:"Supportive environment and coworkers / active exchange / productive discussion / practical application of learning",zh:"好的環境與工作夥伴/積極往來/討論/學以致用"},reversed:{en:"Lack of coordination / inability to adapt flexibly / isolation / inability to delegate and carrying everything alone",zh:"欠缺協調性/無法臨機應變/孤立/無法分配工作而全部自己扛起"}},interpersonal:{upright:{en:"Expanding friendships / conversation / exchange with different backgrounds or values / genuine interaction",zh:"拓展交友關係/交談/與身處不同環境或價值觀的人交流/誠實的往來"},reversed:{en:"Closed heart / non-cooperation / one-way conversation / discord / not listening",zh:"不敞開心胸/不配合對方/單方面的對話/失和/不聽人說話"}},others:{upright:{en:"Well arranged / effective treatment / obtaining medicine or food / smooth travel",zh:"安排得當/有效果的治療/取得藥物或食物/交通順暢"},reversed:{en:"Unable to make use / often futile / ineffective medicine or food / poor adaptation / traffic delays",zh:"無法活用/經常徒勞無功/無效藥物或食物/適應不良/交通阻塞或誤點"}}}},{id:"the-devil",name:{en:"The Devil",zh:"惡魔"},arcana:"major",suit:null,number:15,description:{en:"A naked man and woman are chained before the Devil, yet the chains are loose. The card shows the mind captured by desire and pleasure rather than the body.",zh:"赤身裸體的男女被惡魔擄獲，但鎖鏈綁得很鬆。這張牌顯示被擄獲的並非身體，而是耽溺並墮落於享樂中的心靈。"},coreKeyword:{en:"Binding curse",zh:"咒縛"},meaning:{upright:{en:"Losing to the devil within / consumed by temptation and desire",zh:"敗給心裡的惡魔/無法抗拒誘惑而被欲望吞噬"},reversed:{en:"Fighting the devil within / attempting to control desire and cut unhealthy bonds",zh:"與心裡的惡魔交戰/試圖控制欲望並斬斷不良關聯"}},readingAspects:{currentSituation:{upright:{en:"Content with the present / bound and stagnant / temptation approaching / risk of losing everything through complacency / desire and chaos",zh:"安於現況/受到束縛而沒有進步/面臨誘惑/很可能因稍微鬆懈而失去一切/順從欲望/失序環境"},reversed:{en:"Realizing this cannot continue / opportunity to escape the present / breaking long-held chains / making amends for past deception",zh:"認為這樣下去不行，試圖擺脫現況/回到正軌上的機會/斬斷長年咒縛/為曾經鬼迷心竅作補償"}},innerState:{upright:{en:"Knowing it's wrong but unable to stop / possessiveness stirred / making excuses / dependent / irritable / not entirely negative",zh:"明知不好卻無法停止/占有欲受到刺激/認為沒辦法而找藉口/撒嬌或依賴心強/脾氣暴躁/並非全然負面"},reversed:{en:"No awareness of wrongdoing / determined to break free / attempting self-control / confronting inferiority complex",zh:"沒有正在做壞事的自覺/下定決心試圖擺脫現狀/試圖壓抑自己/面對自卑感"}},rootCause:{upright:{en:"Reason is ineffective / unable to suppress wanting more / yearning for what's forbidden / weak willpower / thrill-seeking",zh:"理智起不了作用/無法壓抑還想要更多的欲望/憧憬禁忌/意志薄弱/追求刺激的心理"},reversed:{en:"No genuine commitment to change / prone to falling again / one mistake / a little is fine mentality / self-control fails",zh:"並沒有認真打算改變現況/一不留神就鬼迷心竅/一次錯誤/一點點就好的姑息/自我控制不起作用"}},development:{upright:{en:"Being tempted / irresistible attraction / unconscious dependency / bewitching events / one moment of weakness loses everything / delays",zh:"受到引誘/無可救藥地被某事物吸引/下意識地依賴/鬼迷心竅般的事件/一瞬間迷惘導致失去一切/拖延"},reversed:{en:"Escaping temptation / correcting bad habits / ending relationships / correcting flaws / rebirth",zh:"逃離誘惑/改掉壞毛病或習慣/斷絕關係的事件/改正自己的缺點/蛻變重生"}},advice:{upright:{en:"Overcome temptation / beware seductive words / avoid things that become habits / beware people who lead you astray",zh:"戰勝誘惑/當心甜言蜜語/不要接近可能變成壞習慣的事物/要注意會引你墮落的人或邪惡念頭的人"},reversed:{en:"Trust your heart / maintain physical distance / do not slander or bully / avoid illegal or immoral acts / make no excuses",zh:"相信自己的內心/保持物理上的距離/切勿說人壞話或欺凌/避免觸法或違背倫常/完全不找藉口"}}},contextualMeanings:{love:{upright:{en:"Jealousy / dependent love / infidelity / dangerous romance / toxic bond / restriction / physical-only connection / domestic abuse",zh:"嫉妒/依賴戀愛/出軌/危險的戀情/孽緣/受到拘束/只在乎肉體的戀情/家暴"},reversed:{en:"Attempting to improve the relationship / escaping love's bondage / cutting toxic ties / correcting the heart / liberation",zh:"試圖改善關係/逃離戀愛的束縛/試圖斬斷孽緣/端正內心/解放"}},work:{upright:{en:"Cannot resign / attachment to position / lawlessness / corruption / deceiving yourself at work / mutual deception",zh:"無法辭去工作/執著於立場/違法/貪污/在工作上欺騙自己/互相欺騙"},reversed:{en:"Finally retiring / noticing unfair treatment / hoping for improvement",zh:"終於可以退休/察覺不合理的對待/期望改善"}},interpersonal:{upright:{en:"Your weakness being exploited / meeting someone disliked / bad friends / entangling person / crude conversation / unreliable person",zh:"被掌握弱點/與討厭的人見面/壞朋友/糾纏不休的人/低級的對話/吊兒郎當的人"},reversed:{en:"Cutting toxic ties / attempting to express your views / avoiding the other / pursuing healthy relationships",zh:"斬斷惡緣/試圖表達自己的意見/避開對方/以健康的人際關係為目標"}},others:{upright:{en:"Lack of common sense / chaos / waste / ugliness / filth / fear / foul play / lust / bad habits / unethical acts",zh:"沒有常識/失序/浪費/醜陋/骯髒/恐懼/犯規/好色/陋習/違反倫理道德的事"},reversed:{en:"Protecting order / escaping dependency / remaining conscience / attempting to overcome fear",zh:"試圖守護常識或秩序/擺脫依賴/剩餘的良心/試圖戰勝恐懼"}}}},{id:"the-tower",name:{en:"The Tower",zh:"高塔"},arcana:"major",suit:null,number:16,description:{en:"Lightning strikes the tower and the crown falls. The scene depicts shocking transformation, unforeseen accident, and destruction that clears the way for something new.",zh:"高塔因驚人的雷電而崩塌，王冠掉落。這張牌意味衝擊性的變化、預期外的意外，以及破壞後的新生。"},coreKeyword:{en:"Destruction",zh:"破壞"},meaning:{upright:{en:"A sudden shock arrives / the current situation changes instantly",zh:"突然降臨的衝擊/瞬間改變現況"},reversed:{en:"A shock that arrives gradually afterward / tension and collapse extend gradually",zh:"之後慢慢抵達的衝擊/緊張與崩毀逐漸延長"}},readingAspects:{currentSituation:{upright:{en:"Changing fortune / unexpected accident / stunned without knowing what happened / stage of shifting beliefs / surprising but not necessarily bad",zh:"變化的運氣/發生出乎意料的意外/不知道發生什麼事而茫然自失/改變想法的階段/吃驚但不糟糕的狀況"},reversed:{en:"Gradual collapse / seems like it will change but doesn't / anxious state / generational shift progressing slowly / timing has passed",zh:"某些事物緩緩崩毀/似乎要改變又沒能改變，令人焦慮不安/世代交替緩緩進行/時機已過，只等消逝"}},innerState:{upright:{en:"Wanting change / sudden awakening / questioning what you have been / thunderbolt-like revelation / wanting to express your individuality",zh:"想要改變/猛然醒悟/懷疑至今為止的自己究竟是什麼/受到彷彿天打雷劈的衝擊/想要更加發揮個性"},reversed:{en:"Resistance to change / preferring the status quo / rejecting new things / not accepting the situation / hoping not to be rushed / stress-induced self-abandonment",zh:"不想改變/維持現狀就好/抗拒新的事物/不接受狀況/希望不要催促/因壓力而自暴自棄"}},rootCause:{upright:{en:"Only the negative shows but isn't the real problem / sudden development prevents calm thinking / driven by unstoppable impulse",zh:"只是顯現壞的一面，不構成問題/突如其來的發展令人無法冷靜/被連本人都無法阻止的衝動驅使"},reversed:{en:"Shaking requires root-level improvement, not just first aid / outdated systems / outdated thinking / narrow capacity to accept new things",zh:"動搖不只採取應急處置，而需要從根本改善/系統老化/思考方式過時/無法接受新事物的狹窄器量"}},development:{upright:{en:"Sudden developments / unexpected personal actions / bold plan changes / unavoidable events / witnessing a new side of someone",zh:"面臨突然的發展/做出連自己都意想不到的行動/大膽變更計畫/以一己之力無法防止的事態/窺見某人新的一面"},reversed:{en:"Current state cannot continue / unavoidable change / resistance prolongs suffering / shock felt gradually afterward",zh:"至今狀態不會持續/面臨不得不改變的事態/愈是抗拒，痛苦拖得愈長/之後慢慢感覺到的衝擊"}},advice:{upright:{en:"Try a different approach / chance to restart your life / bold action is better / discard broken things rather than trying to fix them",zh:"嘗試與至今不同的做法/讓人生重新來過的機會/要做就一口氣大膽前進反而好/壞掉的事物與其修理，不如直接處理掉"},reversed:{en:"Understand gradual collapse cannot be stopped / let your heart adapt to reality / believe destruction brings new opportunity",zh:"明白逐漸毀壞的命運無法阻止/一點一點讓自己的心順應現實/相信破壞現況就能獲得新的機會"}}},contextualMeanings:{love:{upright:{en:"Stimulating romance / bold action / heartfelt conversation / breakup / change of heart / lightning-fast marriage / immediate physical intimacy",zh:"刺激的戀情/行動大膽/推心置腹地交談/別離/變心/閃電結婚/一相遇立刻有肉體關係"},reversed:{en:"Regret after conflict / gradually realizing breakup / depressing memories",zh:"爭執後的懊悔/一點一點意識到分手/每次回想都感到沮喪的場面"}},work:{upright:{en:"Situation transforms completely / sudden resignation or job change / radical reform / trouble / bankruptcy",zh:"狀況一百八十度轉變/突然辭職或跳槽/大膽改造/麻煩/破產"},reversed:{en:"Cannot change methods / stagnant performance / tense workplace / flaws gradually appearing",zh:"無法改變做法/業績停滯不前/令人緊張的職場/一點一點露出破綻"}},interpersonal:{upright:{en:"Emotional upheaval / serious argument / relationship transformation / person who breaks conventions / shocking statements",zh:"情感崩毀/大吵一架/關係改變/打破常識的人/衝擊性的發言"},reversed:{en:"Emotional explosion / cannot suppress what you want to say / gradually speaking out / difficult to understand person / volatile situation",zh:"情感爆發/無法壓抑想說的話/一點一點說出口/無法理解的對象/一觸即發"}},others:{upright:{en:"Major disaster / unexpected injury / strong personality / gamble / sudden collapse / significant impact / fundamental reform",zh:"大災害/意外受傷/很有個性/打賭/突然倒下/衝擊/根本性的改革"},reversed:{en:"Minor disaster / slow collapse in unchangeable situation / avoiding worst damage / barely protecting yourself",zh:"小災害/在無法改變的情況下緩緩崩毀/免於最糟受害/自身難保"}}}},{id:"the-star",name:{en:"The Star",zh:"星星"},arcana:"major",suit:null,number:17,description:{en:"A naked woman pours water under shining stars. The bright star has long guided travelers and represents ideals, hope, purity, and emerging talent.",zh:"赤裸少女在閃耀星光下倒水。天際的星星自古指引旅人，也暗示今後將開花結果的才華、理想與希望。"},coreKeyword:{en:"Hope",zh:"希望"},meaning:{upright:{en:"Moving toward a bright future / following hope with confidence that you are on the right path",zh:"迎向光明的未來/頭頂的希望之星證明正走在正確道路上"},reversed:{en:"Nothing materializes and everything drifts away / hope turns to disappointment",zh:"什麼也無法實現地隨波消逝/希望變成失望"}},readingAspects:{currentSituation:{upright:{en:"Seeing a glimmer of hope / anticipation for someone or something / luck increasing with future prospects / motivated days / good health and spirit",zh:"看見希望之光/對某事或某人產生期待/隨著未來態勢增加的運氣/感覺到幹勁的每一天/身心良好"},reversed:{en:"Losing your guiding star / everything reset to the beginning / expected events delayed / disappointing developments / gloomy days without hope",zh:"失去了引導的星星/事物一筆勾銷回到原點/期待的活動延期/發展令人掃興/不對未來抱持希望，過著悶悶不樂的每一天"}},innerState:{upright:{en:"Finding a purpose / having an admired figure / spiritual stability / inspired / excitement about the future",zh:"找到目標/有了憧憬對象/心有依靠，精神穩定/擁有靈感/對未來雀躍不已"},reversed:{en:"Unable to foresee the future / confused / losing your purpose / disillusionment / discouragement / pessimism / thinking everything is wasted",zh:"無法預測未來而混亂/失去目標/對憧憬對象幻滅/對某事沮喪/對未來悲觀/認為無論做什麼都是白費工夫"}},rootCause:{upright:{en:"The goal itself contains problems / timing issues / needing solid data rather than optimism / ideals too lofty to reach",zh:"目的或目標本身蘊含問題根源/時間上的問題/需要明確資料而非樂觀預測/理想過高無法觸及"},reversed:{en:"Most efforts go to waste / squandering labor or time / all talk with no substance / just going through the motions without learning",zh:"所做的事多為白費工夫/浪費勞力或時間/全是漂亮空談而無內容/只是走完流程而沒有累積經驗"}},development:{upright:{en:"Clear path ahead / clue to solving the problem / fortunate developments arrive one after another / receiving support / abilities recognized",zh:"預測明確/理出解決問題的頭緒/出乎意料的幸運發展接踵而來/受人提拔/才華或實力獲得認同"},reversed:{en:"Hard to predict / losing the clue / all prior work wasted / good fortune disappears / disappointment / gap between ideal and reality",zh:"難以預測/失去解決問題的頭緒/至今所做的一切都是白費工夫/好事付諸流水/令人失望/面對理想與現實落差"}},advice:{upright:{en:"Hold onto hope / maintain a positive mindset / believing makes you the star / actively embrace new ideas and dreams",zh:"繼續抱持希望/抱持積極的心情/只要相信，你本身就會成為星星/積極採用新點子或想做的事"},reversed:{en:"Leave the past behind and find new goals / focus on better things instead of negativity / first dream about what's actually achievable",zh:"將過去全部遺忘，尋找新的目標/與其看消極負面，不如關注更美好的事物/首先描繪可能實現的夢想"}}},contextualMeanings:{love:{upright:{en:"Hopeful romance / relationship develops / ideal partner / admired person / beautiful person / selfless love",zh:"抱持希望的戀情/戀情有發展/理想的情人/憧憬的對象/美麗的人/無償的愛"},reversed:{en:"Idealism too high / narcissism / emotionally unable to keep pace / pessimism / unable to take initiative in romance",zh:"理想過高/自戀/心情無法跟上/悲觀/在戀愛上無法積極面對"}},work:{upright:{en:"Talents shining / setting goals / future star / peak performance / foresight",zh:"才華發光發熱/擬定目標/成為明日之星/狀況絕佳/有先見之明"},reversed:{en:"Failure / cannot see the goal / not adopted / pressured by demands / poor judgment / wasted effort",zh:"失敗/看不見目標/不採用/被業務緊逼/誤判/努力白費"}},interpersonal:{upright:{en:"Inner nourishment from relationships / inspiration or insights / sincere healthy friendship",zh:"與人相處使內心獲得滋潤/獲得靈感或提示/誠心誠意/健康的友情"},reversed:{en:"Too much empty talk without results / treating without seeing results / increased waste from togetherness",zh:"廢話過多而沒有實際結果/不知為何請了客/只要在一起就會增加亂花錢"}},others:{upright:{en:"Good health / recovery / purity / effective medicine / alcoholic beverages / clear night",zh:"身體健康/身體狀況恢復/純真/藥物見效/酒精飲料/晴朗的夜晚"},reversed:{en:"Inner dehydration / cannot enjoy / poor health / lost / hopeless / broken relationships / impurities",zh:"內心失去滋潤/無法享受/不健康/迷失/不抱持希望/翻臉/混有雜質"}}}},{id:"the-moon",name:{en:"The Moon",zh:"月亮"},arcana:"major",suit:null,number:18,description:{en:"The sorrowful Moon shines over a dim landscape where visibility is poor. Dogs, a wolf, and a crayfish suggest anxiety rising from the unconscious.",zh:"面帶愁容的月亮高掛天際，月光下的一切朦朧不清。狗、狼與螯蝦呈現潛意識中的不安逐漸浮上檯面。"},coreKeyword:{en:"Mystery",zh:"神祕"},meaning:{upright:{en:"Viewing reality through illusion / uncertainty, anxiety, secrets, and unclear outlines",zh:"透過幻想看著現實/曖昧不明、不安、祕密與輪廓不清"},reversed:{en:"Gradually seeing through to reality / illusions fade as dawn approaches",zh:"一點一點地看得見現實/幻象消失並逐漸明晰"}},readingAspects:{currentSituation:{upright:{en:"Changeable unstable fortune / unexplained irritation / persistent worries / someone attempting deception is near",zh:"善變而不穩定的運氣/原因不明的煩躁感/正在擔心的事揮之不去/有試圖欺騙你的人接近"},reversed:{en:"Clarity in many ways / reality suddenly becomes visible / anxiety fades / familiar surroundings suddenly seem worn out",zh:"就各種意義上清醒的時候/眼前變得清晰而突然看見現實/不安消散/至今所處之地突然看起來老舊不堪"}},innerState:{upright:{en:"Cannot understand the other's thoughts / wavering / unclear anxiety / distrust of someone / something to hide / only seeing what you want",zh:"搞不清楚對方的想法/動搖/說不清楚的不安感/對某人不信任/有想隱瞞的事/只看想看的事物"},reversed:{en:"Seeing through betrayal, secrets, concealment, or lies but pretending not to / disillusionment / wanting to share the truth",zh:"看穿背叛、祕密、隱瞞或謊言，卻裝作沒察覺/對對方幻滅/回過神來想把真心話說給別人聽"}},rootCause:{upright:{en:"Over-interpreting others' actions or psychology / not facing reality / unresolved matters / someone manipulating information",zh:"過度解讀對方的行動或心理/沒有確實正視現實/存在尚未釐清的事/某人正在操縱情報"},reversed:{en:"Truth cannot be fully hidden / lies and falsehoods increasingly obvious / flaws exposed / old methods no longer work / calmly seeing real ability",zh:"事實無法徹底隱瞞/謊言或虛偽接二連三明朗化/露出破綻/至今做法行不通/冷靜認清自己的實力"}},development:{upright:{en:"Cannot predict outcomes / everything is vague / hidden enemies exist / lies and traps everywhere / anxious actions cause later trouble",zh:"無法預測/一切都顯得模糊不清/存在隱藏的敵人/遍布謊言或陷阱/因不安採取的行動日後引發麻煩"},reversed:{en:"Gradually seeing the way forward / vague matters become concrete / wrongdoings exposed / relief from early discovery despite disillusionment",zh:"逐漸看見接下來的發展/曖昧模糊的事變得具體/壞事被揭發/即使幻滅仍慶幸及早發現"}},advice:{upright:{en:"Do not get deeply involved now / maintain distance / negotiate carefully / avoid casual verbal commitments / sometimes overlook things / keep inner thoughts hidden",zh:"現在不要深入接觸，先保持距離/好好交涉，避免貿然口頭約定/視而不見也是必要的/不要表露內心想法"},reversed:{en:"Wake up and face reality / confirm what you truly want / avoid anxiety from assumptions / distinguish reality from fantasy",zh:"清醒過來正視現實/確認內心真正想要的事物/避開因臆測產生的不安或疑惑/區分現實與妄想"}}},contextualMeanings:{love:{upright:{en:"Dishonest behavior / false romance / concealed romance / hidden rival / romantic atmosphere",zh:"態度不誠實/虛偽的戀情/有所隱瞞的戀情/隱藏的情敵/浪漫的氛圍"},reversed:{en:"Noticing the falsehood / emotions suddenly cool / seeing their true face / hidden relationship exposed",zh:"察覺到虛偽/心意突然冷卻/知道對方真實姿態/想隱藏的關係曝光"}},work:{upright:{en:"Cannot grasp the situation / misunderstandings / fabrication / ambiguity / confusion / no guarantees / hostility / theft",zh:"無法掌握狀況/招致誤解/杜撰/曖昧/不知所措/沒有保證/敵意/小偷"},reversed:{en:"Clearly understanding the situation / regaining calm / realistically investigating root causes",zh:"看得清狀況/恢復冷靜/以現實態度掌握調查問題的原因"}},interpersonal:{upright:{en:"Cannot trust / unsure of the other's motives / unable to fully reveal yourself / mutual probing",zh:"無法信任/不知對方目的/不能亮出全部底牌/互相刺探內心想法"},reversed:{en:"Seeing through falsehoods or true nature / suspicions lifted / gradually understanding one another / true feelings expressed",zh:"看穿虛偽或本性/消除嫌疑/漸漸互相理解/說出真正的心情"}},others:{upright:{en:"Distress / unable to find the way / biased perception / fraud / chronic illness / mystery / fatigue",zh:"苦悶難受/找不到路/以有色眼光看待/詐欺/慢性病/謎題/倦怠"},reversed:{en:"Avoiding danger / illness gradually improves / dawn arrives / solving schemes or mysteries / clarifying thoughts",zh:"迴避危險/疾病逐漸痊癒/黎明到來/解開詭計或謎題/整理思緒"}}}},{id:"the-sun",name:{en:"The Sun",zh:"太陽"},arcana:"major",suit:null,number:19,description:{en:"The Sun shines in a clear sky over a naked child on a horse. This card represents the joy of being alive, vitality, growth, and future success.",zh:"晴空萬里的太陽散發光明，赤裸孩童騎在馬上。這張牌呈現活著的喜悅、生命力、成長與成功。"},coreKeyword:{en:"Joy",zh:"歡欣"},meaning:{upright:{en:"Efforts bearing fruit / openly enjoying success and the joy of living",zh:"努力獲得成果/坦率享受成功與活著的喜悅"},reversed:{en:"Unable to see sunlight / insufficient vitality and stunted growth",zh:"看不見陽光/生命力不足並維持不成熟狀態"}},readingAspects:{currentSituation:{upright:{en:"Luck at its peak / waiting for success after your effort / joyful days / sense of fulfillment / rising momentum / abundant energy",zh:"提升到最高峰的運氣/等待努力之後的成功/充滿喜悅的每一天/感覺到充實/後勢看漲/充滿力量"},reversed:{en:"Clouded fortune / effort doesn't go smoothly / unwanted outcomes / nothing feels joyful / unfinished / low energy",zh:"帶有陰霾的運氣/即使努力也不順利/以並非本意的結果告終/無論做什麼都不開心/虎頭蛇尾/身心能量不足"}},innerState:{upright:{en:"Making effort with enjoyment / valuing process as much as results / resolve to overcome difficulties / acceptance of any outcome",zh:"付諸努力且樂在其中/不只結果，也重視過程/有跨越困難的決心與幹勁/無論發生任何事都能接受"},reversed:{en:"Lack of commitment and wanting escape / half-hearted hesitation / self-indulgence / taking support for granted / favoritism",zh:"無法有覺悟而想逃避/半吊子而猶豫不決/太寵愛自己/認為周遭支援理所當然/偏袒某人"}},rootCause:{upright:{en:"Frank honesty backfires / exposing too much / too candid / childish behavior / immaturity damaging reputation",zh:"率直無虛假的態度造成反效果/過度暴露內心/話過於老實/行為孩子氣/精神幼稚導致聲譽不佳"},reversed:{en:"Distorted thinking / unable to be honest / overly cautious / credit stolen / efforts go unnoticed / insufficient effort",zh:"想法扭曲而無法坦率/過度謹慎/功勞被搶/明明有功勞卻不被關注/努力不足"}},development:{upright:{en:"Receiving attention from others / praised publicly / success or results bringing pride / effort recognized",zh:"受到周遭矚目/做出能在眾人面前受稱讚的事/獲得成功或成果而驕傲/努力獲得認同"},reversed:{en:"Not receiving expected attention / standing out unwillingly / little reward despite effort / motivation drops significantly",zh:"不如預期般受到矚目/在並非本意下過於顯眼/儘管努力，回報很少/動機明顯低落"}},advice:{upright:{en:"Enjoy while moving closer to success / maintain cheerfulness / continue at your current pace / be yourself rather than imitating / greet with a smile",zh:"享受期間也與成功愈來愈接近/保持心情開朗/按照目前步調前進即可/比起模仿別人，不如做自己/面帶笑容打招呼"},reversed:{en:"Notice unproductive effort / self-promotion is vital / push upward once more / maintain a healthy lifestyle",zh:"察覺自己正在做無謂努力/努力推銷自己很重要/再加把勁朝上方邁進/維持健康生活型態"}}},contextualMeanings:{love:{upright:{en:"Love realized / blessed by others / honest partner / healthy romance / cooperating for romance",zh:"戀情實現/受到周遭祝福/誠實的對象/健康的戀情/為戀愛而合作的關係"},reversed:{en:"Anxiety about romance's outcome / unable to be honestly happy / difficult to trust despite wanting to",zh:"對戀情結果感到不安/無法坦率高興的戀情/即使想信任也難以相信的對象"}},work:{upright:{en:"Major success / promotion / light returning / grasping glory / enjoyable even if challenging",zh:"獲得成功/晉升/重見光明/掌握榮耀/即使難熬的工作也能愉快完成"},reversed:{en:"Cannot truly feel success / unable to recognize yourself / unwilling to work hard / unhappy even when praised",zh:"無法確實感受到成功/無法認同自己/不想努力/就算受到稱讚也不開心"}},interpersonal:{upright:{en:"No deception / someone who revitalizes your spirit / no conflicts of interest / healthy relationship / fulfilling and enjoyable",zh:"毫無隱瞞/能讓人重振精神的對象/沒有利害衝突的健康關係/充實而愉快"},reversed:{en:"Interest-driven / cannot smile sincerely / emptiness despite fun",zh:"在意利害關係/無法由衷露出笑容/即便愉快仍感到空虛"}},others:{upright:{en:"Joy / health / spirited energy / hard work / spotlight / child / newborn / daytime / clear sky",zh:"愉快/健康/有精神/能夠努力/聚光燈/孩童/新生兒/白天/晴空萬里"},reversed:{en:"Excessive modesty / cannot enjoy openly / timidity / oversight / physical decline",zh:"謙虛客氣/無法坦率享受/膽怯/疏忽/體力衰退"}}}},{id:"judgement",name:{en:"Judgement",zh:"審判"},arcana:"major",suit:null,number:20,description:{en:"An angel blows a trumpet and the dead rise from their coffins. What was thought finished comes back to life, bringing a decisive opportunity.",zh:"天使吹響號角，下方死者接二連三從棺材裡復活。原本以為已結束的事物生意盎然地復甦，暗示重要機會。"},coreKeyword:{en:"Liberation",zh:"解放"},meaning:{upright:{en:"Seizing a fleeting opportunity / releasing what was once sealed away",zh:"掌握轉瞬間的機會/釋出原本珍藏或封印的事物"},reversed:{en:"Delaying until things freeze again / missing the chance through hesitation",zh:"延遲後就這樣凍結/因猶豫而錯過機會"}},readingAspects:{currentSituation:{upright:{en:"Turning point / forgotten plans or memories revive / opportunity appears near despair / reunion with someone important / time to try again",zh:"轉捩點/遺忘的計畫或記憶復甦/機會在快放棄時降臨/與重要人物重逢/再次挑戰的時刻"},reversed:{en:"No help arrives no matter how long you wait / missing a once-in-a-lifetime chance / opportunity never comes / too late / empty waiting",zh:"再怎麼等也等不到幫手/錯過千載難逢的機會/機會遲遲不降臨/一切為時已晚/空等"}},innerState:{upright:{en:"Feeling liberated and clear / wanting to clarify right from wrong / wanting to make a life decision / almost remembering something important / looking back",zh:"因解放而感覺神清氣爽/想要辨明是非對錯/想做出人生重要決定/就快想起重要事物/回顧過去"},reversed:{en:"Feeling trapped / embarrassing memories / believing it cannot be fixed now / wanting to gloss over and abandon the chance",zh:"受到封閉感折磨/尷尬的回憶/認為事到如今無法挽回/想敷衍了事，將機會連同問題放棄"}},rootCause:{upright:{en:"Deceived by false chances / seeking backup for security / past relationship problems resurface / old ailments recur",zh:"被假機會矇騙/為求保險試圖取得備胎/過去人際關係糾紛重新浮上檯面/舊疾復發"},reversed:{en:"Missing the important occasion / timing is wrong no matter what / forgetting important things / lacking courage and delaying, thus missing the chance",zh:"趕不上重大場合/無論做什麼時機都不對/忘記重要的事/無法鼓起勇氣而拖延，因此錯失機會"}},development:{upright:{en:"Restarting something almost abandoned / deciding without hesitation / choosing what matters most / understanding past meaning / reclaiming lost things",zh:"重新啟動差點放棄的事物/下定決心不再猶豫/選擇最重要的事物/了解過去事件的意義/取回失去的事物"},reversed:{en:"Unable to decide / no choice and circling / opportunity does not come / complete forgetting / cannot move on without settling the past",zh:"無法下定決心/沒能做出選擇，一再兜圈子/目前機會無法降臨/徹底遺忘/不對過去了斷就無法前進"}},advice:{upright:{en:"Treasure this moment / past memories and experience offer hints / do what you can now as best as possible / redemptive success / shelved matters enter execution",zh:"珍惜現在這個瞬間/過去記憶或經驗成為提示/將目前能做的事做到最好即可/成功雪恥/保留至今的事情進入執行階段"},reversed:{en:"Face what you have avoided / do not waste time / decide now / do not expect miracle-like chances / recognize necessity",zh:"面對一直逃避的事物/不要浪費時間/現在就下決定/不要期待奇蹟般的機會/認清究竟有沒有必要"}}},contextualMeanings:{love:{upright:{en:"The person / confession / settling past issues / rekindled romance / marriage decision / remarriage",zh:"認為就是這個人的對象/表白/整理過去/戀情復燃/決心結婚/再婚"},reversed:{en:"Unrequited romance / uncomfortable confession / secret love / unresolved matters / relationship regrets",zh:"戀情沒有結果/尷尬的表白/暗戀/事情沒有做個了斷/戀情上的懊悔"}},work:{upright:{en:"Comeback opportunity / clearing your name / returning to your original purpose / relief / charting direction / success",zh:"起死回生的機會/洗刷污名/回歸初衷/放下心中的大石頭/決定導向成功"},reversed:{en:"Unrewarded effort / missed opportunity / setbacks / prolonged difficult work",zh:"沒有回報的努力/錯失機會/遇到挫折/辛苦的工作延長"}},interpersonal:{upright:{en:"Settling the relationship / decisive moment / reunion / healing ties / important person to get to know beforehand",zh:"把關係做個了斷/一決勝負時/重逢/修復關係/應該事先掌握的重要人物"},reversed:{en:"Gradual distance / fading from memory / hard to repair relationship / impossible reunion / troublesome person",zh:"逐漸疏遠/忘記其存在/關係難以修復/無法重逢/麻煩的人物"}},others:{upright:{en:"Favorable momentum in decisive moment / finding the key / sharp intuition / recovering luck / decisive action",zh:"一決勝負時有利的運勢/找到訣竅/直覺敏銳/恢復好運/乾脆果斷"},reversed:{en:"Disadvantage in decisive moment / cannot find the key / decision postponed / insufficient preparation / expired",zh:"一決勝負時居於劣勢/找不到訣竅/決定延期/準備不足而無法行動/過期"}}}},{id:"the-world",name:{en:"The World",zh:"世界"},arcana:"major",suit:null,number:21,description:{en:"A dancer within a wreath holds wands and is surrounded by the four elemental beings. This card shows a completed world after a long journey.",zh:"花環中央的舞者手持權杖，四角有對應四大元素的聖獸。這張牌顯示一切獲得滿足，象徵歷經漫長時光後的完成。"},coreKeyword:{en:"Completion",zh:"完成"},meaning:{upright:{en:"Achieving your goal and gaining satisfaction / savoring joy before the next stage",zh:"達成目標而獲得滿足/在下一階段前品嚐喜悅"},reversed:{en:"Withdrawing because results are unsatisfying / completion falls short of expectation",zh:"因不滿意的結果而撤退/雖有完成度卻不如預期"}},readingAspects:{currentSituation:{upright:{en:"Excellent luck / satisfied with yourself so far / enviable happiness / problem reaches its final stage / best possible outcome",zh:"運氣絕佳/對至今為止的自己感到滿意/獲得令人羨慕的幸福/問題來到最後階段/得到最棒結果的時候"},reversed:{en:"Sluggish state / not yet achieving satisfying results / neither good nor bad, incomplete performance / unable to meet expectations / unfinished",zh:"萎靡狀態/還不到能獲得滿意結果的階段/不好也不壞的不完全燃燒狀態/沒能回應周遭期待/維持未完成狀態"}},innerState:{upright:{en:"Absorbed in one thing / undivided focus without distraction / satisfaction of complete engagement / everything exists for this / utmost self-affirmation",zh:"熱衷於一件事/毫無雜念的高度專注狀態/獲得完全燃燒的滿足感/認為一切都是為此而存在/最棒的自我肯定感"},reversed:{en:"Too concerned with others' perception to show ability / regret over not giving your all / wrong approach leads to failure / half-finished ending / losing drive",zh:"一味在意周遭視線而無法發揮實力/沒使出全力而懊悔/應對方式錯誤導致功敗垂成/結束方式半吊子而不完全燃燒/失去幹勁"}},rootCause:{upright:{en:"Only staring ahead and responding with focus / unable to see surroundings / overdoing / narcissistic attitude / self-satisfaction not understood",zh:"只緊盯前方專心應對而看不見周遭/做過頭/自戀的態度/自我滿足而得不到理解"},reversed:{en:"No perseverance / wanting to quit at critical moments / leaving important issues until later / lacking power to carry through / no clear vision",zh:"沒有毅力，關鍵時刻試圖放棄/把重要問題留到後面/欠缺貫徹到底的力量/欠缺願景"}},development:{upright:{en:"Best happy ending / long-held wish fulfilled / final results of everything to date / dreams realized / supreme happiness and satisfaction",zh:"最棒的快樂結局/夙願以償/至今所做的一切最後結果出爐/實現夢想/獲得至高無上的幸福滿足感"},reversed:{en:"Result far below target / ending in disappointment / stopping halfway and evading / dreams end as fantasy / enough is enough attitude / harm from pretending",zh:"得到遠低於目標的結果/以不滿意告終/點到為止並閃躲/夢想以空想告終/覺得夠了而敷衍了事/偽裝造成弊病"}},advice:{upright:{en:"Move at your own pace to the very end / believe in those who support you / share your joy with others / the challenge itself has meaning",zh:"直到最後都按照自己的步調前進即可/相信支持自己的人/與周遭分享喜悅/認為挑戰這件事本身就有意義"},reversed:{en:"For big goals, complete small things one by one / filter out external noise / confirm your purpose / do not escape / run fully to the finish",zh:"面對大目標時，先將小事一件件完成/排除局外人的雜音/確認自己的使命/切勿逃避/全力奔跑到最後一刻"}}},contextualMeanings:{love:{upright:{en:"Mutual love / romance bears fruit / respect and trust / happy marriage / blessed relationship",zh:"兩情相悅/戀情有結果/尊敬與信任對方/幸福的婚姻/受祝福的關係"},reversed:{en:"Love taken for granted / no future seen / losing gratitude / romance that won't progress to marriage",zh:"被視為理所當然的戀愛/關係看不見未來/失去感恩之情/不會進展到婚姻的關係"}},work:{upright:{en:"Vocation / smooth progress / achievement regardless of result / no regrets after completion / wanting to change direction",zh:"天職/順利進行/與結果無關的成就感/貫徹到底後毫無遺憾/想更換跑道"},reversed:{en:"Uncertain future / satisfied before reaching goal / arrogance / changing jobs to escape reality",zh:"前途堪憂/達成目標前就已滿足/驕傲/為逃避現實而換工作"}},interpersonal:{upright:{en:"Long-established friendship / nostalgic person or topic / popularity / someone who creates belonging / good companion",zh:"老交情/令人懷念的人物或話題/人望/能創造自己容身之處的人/好夥伴"},reversed:{en:"No expectation for further development / no strong impression either way / distance / limits",zh:"不期望關係進一步發展/無論好壞都沒有留下印象的人物/疏遠/極限"}},others:{upright:{en:"Victory / joy / your own worldview / care from supporters / enlightenment / understanding everything",zh:"勝利/喜悅/只屬於自己的世界觀/受到支持者關照/開悟/理解一切"},reversed:{en:"Whatever attitude / cannot fulfill your role / abilities not fully shown / self-satisfaction / maintaining the status quo",zh:"怎樣都好/無法發揮自己的作用/沒有充分展現的能力/自我滿足/維持現狀"}}}}]}}]);